"use client";

import {
  Avatar,
  AvatarFallback,
  AvatarGroup,
  AvatarGroupCount,
  AvatarImage,
} from "@/registry/default/ui/avatar";
import {
  Popover,
  PopoverPopup,
  PopoverTrigger,
} from "@/registry/default/ui/popover";
import { Skeleton } from "@/registry/default/ui/skeleton";
import {
  Tooltip,
  TooltipPopup,
  TooltipProvider,
  TooltipTrigger,
} from "@/registry/default/ui/tooltip";
import { type BookerAvatar, getInitials } from "./lib/booker-utils";

const maxVisibleAvatars = 4;

type BookerAvatarsProps = {
  avatars?: BookerAvatar[];
  fallbackName?: string;
};

export function BookerAvatars({ avatars, fallbackName }: BookerAvatarsProps) {
  if (!fallbackName) {
    return (
      <Avatar className="[--avatar-size:--spacing(14)]">
        <AvatarFallback className="bg-transparent">
          <Skeleton className="size-full rounded-full" />
        </AvatarFallback>
      </Avatar>
    );
  }

  if (avatars && avatars.length === 0) {
    return null;
  }

  const visibleAvatars =
    avatars && avatars.length > 0
      ? avatars
      : [{ avatarUrl: "", name: fallbackName, profileUrl: "" }];
  const firstAvatar = visibleAvatars[0];

  if (visibleAvatars.length === 1 && firstAvatar) {
    // As the design system's HostAvatars: the avatar is the link.
    return (
      <Avatar
        className="outline-none [--avatar-size:--spacing(14)] focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-card"
        render={
          // biome-ignore lint/a11y/useAnchorContent: the avatar is the content
          <a
            aria-label={firstAvatar.name}
            href={firstAvatar.profileUrl || "#"}
            rel={firstAvatar.profileUrl ? "noreferrer" : undefined}
            target={firstAvatar.profileUrl ? "_blank" : undefined}
          />
        }
      >
        {firstAvatar.avatarUrl ? (
          <AvatarImage alt={firstAvatar.name} src={firstAvatar.avatarUrl} />
        ) : null}
        <AvatarFallback>{getInitials(firstAvatar.name)}</AvatarFallback>
      </Avatar>
    );
  }

  // As the design system's HostAvatars: at most four avatars, then a count
  // that lists the rest. Each avatar is the link itself, so AvatarGroup's
  // overlap and cut-outs apply to it directly.
  const shownAvatars = visibleAvatars.slice(0, maxVisibleAvatars);
  const hiddenAvatars = visibleAvatars.slice(maxVisibleAvatars);
  const hiddenLabel =
    hiddenAvatars.length === 1
      ? "1 more host"
      : `${hiddenAvatars.length} more hosts`;

  return (
    <TooltipProvider delay={0}>
      <AvatarGroup topmost="last">
        {shownAvatars.map((avatar, index) => (
          <Tooltip key={`${avatar.name}-${avatar.avatarUrl}-${index}`}>
            <TooltipTrigger
              render={
                <Avatar
                  aria-label={avatar.name}
                  className="outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-card"
                  render={
                    // biome-ignore lint/a11y/useAnchorContent: the avatar is the content
                    <a
                      href={avatar.profileUrl || "#"}
                      rel={avatar.profileUrl ? "noreferrer" : undefined}
                      target={avatar.profileUrl ? "_blank" : undefined}
                    />
                  }
                />
              }
            >
              <span className="sr-only">{avatar.name}</span>
              {avatar.avatarUrl ? (
                <AvatarImage alt={avatar.name} src={avatar.avatarUrl} />
              ) : null}
              <AvatarFallback>{getInitials(avatar.name)}</AvatarFallback>
            </TooltipTrigger>
            <TooltipPopup>{avatar.name}</TooltipPopup>
          </Tooltip>
        ))}
        {hiddenAvatars.length > 0 ? (
          <Popover>
            <PopoverTrigger
              aria-label={hiddenLabel}
              className="outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-card"
              delay={0}
              nativeButton={false}
              openOnHover
              render={<AvatarGroupCount />}
            >
              +{hiddenAvatars.length}
            </PopoverTrigger>
            <PopoverPopup
              align="start"
              aria-label="Additional hosts"
              side="top"
              tooltipStyle
            >
              <ul className="flex flex-col gap-1">
                {hiddenAvatars.map((avatar, index) => (
                  <li
                    className="font-medium text-xs"
                    key={`${avatar.name}-${index}`}
                  >
                    {avatar.name}
                  </li>
                ))}
              </ul>
            </PopoverPopup>
          </Popover>
        ) : null}
      </AvatarGroup>
    </TooltipProvider>
  );
}

// The Booker calendar's day model, as the design system's
// (calcom/cal `apps/design-system/components/booker-calendar-model.ts`).
// Dates are plain "YYYY-MM-DD" keys and months "YYYY-MM" keys: calendar
// values, not instants.

export type CalendarDayState = {
  /** `"unknown"` while the day's availability has not been loaded. */
  available: boolean | "unknown";
  away?: {
    emoji: string;
    showNotePublicly?: boolean;
    message?: string;
    alternativeHost?: { name?: string | null };
  };
};

export type CalendarDay = { key: string; outside: boolean; hidden: boolean };

export function calendarDate(key: string): Date {
  return new Date(`${key}T12:00:00Z`);
}

export function dateKey(date: Date): string {
  return date.toISOString().slice(0, 10);
}

export function addDays(key: string, amount: number): string {
  const date = calendarDate(key);
  date.setUTCDate(date.getUTCDate() + amount);
  return dateKey(date);
}

// Clamps the day to the target month's end: Jan 31 + 1 month is Feb 28.
export function addMonths(key: string, amount: number): string {
  const date = calendarDate(key);
  const day = date.getUTCDate();
  date.setUTCDate(1);
  date.setUTCMonth(date.getUTCMonth() + amount);
  const end = new Date(
    Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 0),
  );
  date.setUTCDate(Math.min(day, end.getUTCDate()));
  return dateKey(date);
}

export function startOfWeek(key: string, weekStart: number): string {
  return addDays(key, -((calendarDate(key).getUTCDay() - weekStart + 7) % 7));
}

export function isKnownDay(state: CalendarDayState): boolean {
  return state.available !== "unknown";
}

export function isSelectableDay(state: CalendarDayState): boolean {
  if (!isKnownDay(state)) return false;
  if (state.away) {
    return Boolean(state.away.showNotePublicly || state.away.alternativeHost);
  }
  return state.available === true;
}

// Always 42 cells. For the current month, once today reaches the 4th row,
// today's week and the two after it stay visible: the grid extends into the
// next month and drops early weeks only when it must. UTC arithmetic keeps
// the keys stable across timezones.
export function calendarGrid({
  month,
  today,
  weekStart = 0,
  shiftWeeks = true,
  minDate,
  maxDate,
}: {
  month: string;
  today: string;
  weekStart?: number;
  shiftWeeks?: boolean;
  minDate: string;
  maxDate?: string;
}): CalendarDay[] {
  const first = `${month}-01`;
  const naturalStart = startOfWeek(first, weekStart);
  const todayRow = Math.floor(
    (calendarDate(today).getTime() - calendarDate(naturalStart).getTime()) /
      604800000,
  );
  const expanded = shiftWeeks && today.startsWith(month) && todayRow >= 3;
  const shift = expanded ? Math.max(0, todayRow - 3) * 7 : 0;
  const start = addDays(naturalStart, shift);
  return Array.from({ length: 42 }, (_, index) => {
    const key = addDays(start, index);
    const outside = !key.startsWith(month);
    const hidden =
      key < first ||
      (!expanded && outside) ||
      key.slice(0, 7) < minDate.slice(0, 7) ||
      Boolean(maxDate && key.slice(0, 7) > maxDate.slice(0, 7));
    return { key, outside, hidden };
  });
}

// Keeps a selection that is still visible and selectable; otherwise the
// first selectable day in view, unless `autoSelect` is off.
export function resolveSelection(
  selected: string | undefined,
  days: CalendarDay[],
  getDay: (key: string) => CalendarDayState,
  autoSelect = true,
): string | undefined {
  if (
    selected &&
    days.some(
      (day) =>
        !day.hidden && day.key === selected && isSelectableDay(getDay(day.key)),
    )
  ) {
    return selected;
  }
  if (!autoSelect) return undefined;
  return days.find((day) => !day.hidden && isSelectableDay(getDay(day.key)))
    ?.key;
}

export function keyboardDate({
  current,
  key,
  shiftKey = false,
  dir = "ltr",
  weekStart,
  minDate,
  maxDate,
  isSelectable,
  isKnown = () => true,
}: {
  current: string;
  key: string;
  shiftKey?: boolean;
  dir?: "ltr" | "rtl";
  weekStart: number;
  minDate: string;
  maxDate?: string;
  isSelectable: (key: string) => boolean;
  isKnown?: (key: string) => boolean;
}): string | undefined {
  let candidate: string;
  let direction = 1;
  let end = maxDate;
  let start = minDate;
  switch (key) {
    case "Home":
      candidate = startOfWeek(current, weekStart);
      end = addDays(candidate, 6);
      break;
    case "End":
      start = startOfWeek(current, weekStart);
      candidate = addDays(start, 6);
      direction = -1;
      break;
    case "ArrowLeft":
    case "ArrowRight":
      direction = (key === "ArrowRight" ? 1 : -1) * (dir === "rtl" ? -1 : 1);
      candidate = shiftKey
        ? addMonths(current, direction)
        : addDays(current, direction);
      break;
    case "ArrowUp":
    case "ArrowDown":
      direction = key === "ArrowDown" ? 1 : -1;
      candidate = shiftKey
        ? addMonths(current, direction * 12)
        : addDays(current, direction * 7);
      break;
    case "PageUp":
    case "PageDown":
      direction = key === "PageDown" ? 1 : -1;
      candidate = addMonths(current, direction * (shiftKey ? 12 : 1));
      break;
    default:
      return undefined;
  }
  start = start < minDate ? minDate : start;
  if (maxDate && (!end || end > maxDate)) end = maxDate;
  if (candidate < start) candidate = start;
  if (end && candidate > end) candidate = end;
  for (
    let attempt = 0;
    attempt < 366 && candidate >= start && (!end || candidate <= end);
    attempt++
  ) {
    // Unknown is a focus intent for the owner to load, not a confirmed
    // selectable date.
    if (!isKnown(candidate)) return candidate;
    if (isSelectable(candidate)) return candidate;
    candidate = addDays(candidate, direction);
  }
  return undefined;
}

// For callers that hold local `Date`s: a date's own year, month and day as a
// key, and a key back as local midnight.
export function localDateKey(date: Date): string {
  const pad = (value: number) => String(value).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

export function localDate(key: string): Date {
  const [year = 0, month = 1, day = 1] = key.split("-").map(Number);
  return new Date(year, month - 1, day);
}

// Cal's weekStart is a day name ("Monday"); the calendar takes 0 = Sunday …
// 6 = Saturday.
const WEEKDAYS = [
  "sunday",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday",
];

export function toWeekStart(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isInteger(value)) {
    return ((value % 7) + 7) % 7;
  }
  if (typeof value !== "string") return undefined;
  const index = WEEKDAYS.indexOf(value.trim().toLowerCase());
  return index === -1 ? undefined : index;
}

"use client";

// The Booker's month calendar, as the design system's "Booker calendar"
// (calcom/cal `apps/design-system/components/booker-calendar-preview.tsx`).
// The design system simulates its three layouts; the Booker uses container
// queries on its card: mobile below `@3xl`, compact `@3xl` to `@5xl`, wide
// from `@5xl`. No motion for now.

import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react";
import {
  type ComponentProps,
  type ReactElement,
  type ReactNode,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";
import { Skeleton } from "@/registry/default/ui/skeleton";
import {
  Tooltip,
  TooltipCreateHandle,
  TooltipPopup,
  TooltipProvider,
  TooltipTrigger,
} from "@/registry/default/ui/tooltip";
import {
  addDays,
  addMonths,
  type CalendarDayState,
  calendarDate,
  calendarGrid,
  isKnownDay,
  isSelectableDay,
} from "./booker-calendar-model";
import { bookerHeadingClassName } from "./booker-heading";
import { useBookerCalendarFocus } from "./use-booker-calendar-focus";

export type { CalendarDayState } from "./booker-calendar-model";

// The design system's per-layout geometry, as container queries.
const styles = {
  cell: "aspect-square @max-3xl:aspect-auto @max-3xl:h-9",
  gap: "gap-1 @5xl:gap-1.5",
  heading: "@5xl:ps-1 text-lg @3xl:@max-5xl:text-base",
  hitArea: "after:-inset-0.5 @5xl:after:-inset-0.75",
  monthLabel: "end-1 top-1 @3xl:top-1.5 @5xl:end-1.5",
  row: "mt-1 @5xl:mt-1.5",
};

// English defaults. Localize by passing translated strings via `labels`;
// date, weekday and month names come from `locale` via `Intl`.
export const CALENDAR_LABELS = {
  previousMonth: "Go to the previous month",
  nextMonth: "Go to the next month",
  navigation: "Calendar navigation",
  today: "Today",
  selected: "selected",
  away: "Out of office",
  loading: "Loading availability",
};

export type CalendarLabels = typeof CALENDAR_LABELS;

const formatters = new Map<string, Intl.DateTimeFormat>();

// Calendar dates stay Gregorian whatever the language.
export function formatCalendarDate(
  key: string,
  locale: string,
  options: Intl.DateTimeFormatOptions,
): string {
  const id = `${locale}|${JSON.stringify(options)}`;
  let formatter = formatters.get(id);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(locale, {
      ...options,
      calendar: "gregory",
      timeZone: "UTC",
    });
    formatters.set(id, formatter);
  }
  return formatter.format(calendarDate(key));
}

// Month and year; the year is muted via formatToParts so it stays
// locale-correct (some locales render "2026 June").
function CalendarMonthCaption({
  month,
  locale,
}: {
  month: string;
  locale: string;
}): ReactElement {
  const formatter = new Intl.DateTimeFormat(locale, {
    calendar: "gregory",
    month: "long",
    timeZone: "UTC",
    year: "numeric",
  });
  return (
    <div className={cn(bookerHeadingClassName, styles.heading)}>
      {formatter
        .formatToParts(calendarDate(`${month}-01`))
        .map((part, index) =>
          part.type === "year" ? (
            <span
              key={`${part.type}-${index}`}
              className="text-muted-foreground/72"
            >
              {part.value}
            </span>
          ) : (
            part.value
          ),
        )}
    </div>
  );
}

type TooltipHandle = ReturnType<typeof TooltipCreateHandle<string>>;

function CalendarDayButton({
  date,
  state,
  selected = false,
  today = false,
  loading = false,
  focused = false,
  monthLabel,
  locale,
  labels,
  tooltipHandle,
  ...buttonProps
}: Omit<ComponentProps<"button">, "children"> & {
  date: string;
  state: CalendarDayState;
  selected?: boolean;
  today?: boolean;
  loading?: boolean;
  focused?: boolean;
  monthLabel?: string;
  locale: string;
  labels: CalendarLabels;
  tooltipHandle?: TooltipHandle;
}): ReactElement {
  const ref = useRef<HTMLButtonElement>(null);
  const disabled = !isSelectableDay(state);
  useEffect(() => {
    if (focused && !loading && !disabled) ref.current?.focus();
  }, [focused, loading, disabled]);
  const label = [
    today ? labels.today : undefined,
    formatCalendarDate(date, locale, {
      day: "numeric",
      month: "long",
      weekday: "long",
      year: "numeric",
    }),
    state.away ? labels.away : undefined,
    selected ? labels.selected : undefined,
  ]
    .filter(Boolean)
    .join(", ");

  const button = (
    <button
      {...buttonProps}
      aria-current={today ? "date" : undefined}
      aria-label={label}
      className={cn(
        "in-data-disabled:pointer-events-none relative flex w-full items-center justify-center rounded-lg bg-muted in-data-disabled:bg-transparent in-data-selected:bg-primary font-medium in-data-disabled:font-normal in-data-selected:text-primary-foreground text-foreground tabular-nums in-data-disabled:opacity-50 outline-none after:absolute not-in-data-disabled:not-in-data-selected:hover:ring-2 not-in-data-disabled:not-in-data-selected:hover:ring-primary/72 focus-visible:z-1 focus-visible:ring-2 focus-visible:ring-primary/72 sm:text-sm",
        styles.cell,
        styles.hitArea,
      )}
      disabled={disabled || loading}
      ref={ref}
      type="button"
    >
      {state.away ? (
        <span aria-hidden="true">{state.away.emoji}</span>
      ) : (
        formatCalendarDate(date, locale, { day: "numeric" })
      )}
      {monthLabel ? (
        <span
          aria-hidden="true"
          className={cn(
            "pointer-events-none absolute font-medium in-data-selected:text-primary-foreground/72 text-[10px] text-muted-foreground leading-none",
            styles.monthLabel,
          )}
        >
          {monthLabel}
        </span>
      ) : null}
    </button>
  );
  let content: ReactNode = button;
  if (loading) {
    content = <Skeleton className={cn("w-full rounded-lg", styles.cell)} />;
  } else if (tooltipHandle && !disabled) {
    content = (
      <TooltipTrigger
        handle={tooltipHandle}
        payload={formatCalendarDate(date, locale, { month: "long" })}
        render={button}
      />
    );
  }
  return (
    <div
      className={cn(
        "w-full",
        today &&
          !loading &&
          "*:before:pointer-events-none *:before:absolute *:before:start-1/2 *:before:bottom-1/7 *:before:z-1 *:before:size-1 *:before:-translate-x-1/2 *:before:rounded-full *:before:bg-primary [&[data-selected]>*]:before:bg-primary-foreground",
      )}
      data-away={Boolean(state.away) || undefined}
      data-disabled={disabled || undefined}
      data-selected={selected || undefined}
      data-today={today || undefined}
    >
      {content}
    </div>
  );
}

export type BookerCalendarProps = {
  className?: string;
  /** The displayed month, "YYYY-MM". */
  month: string;
  /** Today in the attendee's timezone, "YYYY-MM-DD". */
  today: string;
  /** The first bookable date; earlier months can't be shown. */
  minDate: string;
  /** The last bookable date, when the booking window has one. */
  maxDate?: string;
  selected?: string;
  onSelect: (date: string) => void;
  /**
   * `preserveSelection` is true for keyboard moves: focus changed month, the
   * selection didn't.
   */
  onMonthChange: (month: string, preserveSelection?: boolean) => void;
  /** Each day's state; `{ available: "unknown" }` until its range loads. */
  getDay: (date: string) => CalendarDayState;
  /**
   * First day of the week (0 = Sunday … 6 = Saturday): the event type's,
   * falling back to the host's.
   */
  weekStart?: number;
  /** BCP-47 locale for day, month and weekday names. */
  locale?: string;
  dir?: "ltr" | "rtl";
  labels?: Partial<CalendarLabels>;
  loading?: "initial" | "availability";
  /**
   * For the current month, once today reaches the 4th row, keep its week
   * and the next two visible. On by default.
   */
  shiftWeeks?: boolean;
};

export function BookerCalendar({
  className,
  month,
  today,
  minDate,
  maxDate,
  selected,
  onSelect,
  onMonthChange,
  getDay,
  weekStart = 0,
  locale = "en-US",
  dir = "ltr",
  labels: labelsProp,
  loading,
  shiftWeeks = true,
}: BookerCalendarProps): ReactElement {
  const labels = { ...CALENDAR_LABELS, ...labelsProp };
  // One tooltip per calendar, reused by every next-month day.
  const [tooltipHandle] = useState(() => TooltipCreateHandle<string>());
  const days = useMemo(
    () =>
      calendarGrid({ maxDate, minDate, month, shiftWeeks, today, weekStart }),
    [month, today, minDate, maxDate, weekStart, shiftWeeks],
  );
  const getState = (key: string): CalendarDayState => {
    const state = getDay(key);
    if (key >= minDate && (!maxDate || key <= maxDate)) return state;
    return {
      available: false,
      away: state.away ? { emoji: state.away.emoji } : undefined,
    };
  };
  const focus = useBookerCalendarFocus({
    days,
    dir,
    getDay,
    loading,
    maxDate,
    minDate,
    month,
    onMonthChange,
    selected,
    today,
    weekStart,
  });
  const overflowFirst = days.find((day) => !day.hidden && day.outside)?.key;
  const monthName = formatCalendarDate(`${month}-01`, locale, {
    month: "long",
    year: "numeric",
  });
  const weekdays = Array.from({ length: 7 }, (_, index) =>
    addDays("2026-09-06", (weekStart + index) % 7),
  );

  return (
    <div
      aria-busy={Boolean(loading)}
      className={cn("w-full select-none", className)}
      data-slot="booker-calendar"
      dir={dir}
      lang={locale}
      ref={focus.rootRef}
    >
      <div className="flex w-full flex-col gap-2">
        <div aria-atomic="true" aria-live="polite" className="sr-only">
          {loading ? labels.loading : monthName}
        </div>
        <div className="flex h-10 items-center justify-between sm:h-9">
          {loading === "initial" ? (
            <Skeleton className="h-6 w-28" />
          ) : (
            <>
              <CalendarMonthCaption locale={locale} month={month} />
              <nav
                aria-label={labels.navigation}
                className="flex items-center gap-1"
              >
                <Button
                  aria-label={labels.previousMonth}
                  disabled={month <= minDate.slice(0, 7)}
                  onClick={() =>
                    onMonthChange(addMonths(`${month}-01`, -1).slice(0, 7))
                  }
                  size="icon-lg"
                  variant="ghost"
                >
                  <ChevronLeftIcon
                    aria-hidden="true"
                    className="rtl:rotate-180"
                  />
                </Button>
                <Button
                  aria-label={labels.nextMonth}
                  disabled={Boolean(maxDate && month >= maxDate.slice(0, 7))}
                  onClick={() =>
                    onMonthChange(addMonths(`${month}-01`, 1).slice(0, 7))
                  }
                  size="icon-lg"
                  variant="ghost"
                >
                  <ChevronRightIcon
                    aria-hidden="true"
                    className="rtl:rotate-180"
                  />
                </Button>
              </nav>
            </>
          )}
        </div>
        <TooltipProvider delay={0}>
          <table
            aria-label={monthName}
            aria-multiselectable={false}
            className="w-full outline-offset-2 focus-visible:outline-2 focus-visible:outline-primary"
            // biome-ignore lint/a11y/noNoninteractiveElementToInteractiveRole: the design system's date grid, which takes focus when a keyboard move finds no selectable date
            role="grid"
            tabIndex={-1}
          >
            <thead>
              <tr className="flex w-full gap-1 py-2">
                {weekdays.map((key) => (
                  <th
                    aria-label={formatCalendarDate(key, locale, {
                      weekday: "long",
                    })}
                    className="flex-1 font-medium text-muted-foreground/72 text-xs"
                    key={key}
                    scope="col"
                  >
                    {loading === "initial" ? (
                      <Skeleton className="mx-auto my-0.5 h-3 w-6" />
                    ) : (
                      formatCalendarDate(key, locale, { weekday: "short" })
                    )}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {Array.from({ length: 6 }, (_, row) => (
                <tr
                  className={cn("flex w-full", styles.row, styles.gap)}
                  key={days[row * 7]?.key}
                >
                  {days.slice(row * 7, row * 7 + 7).map((day) => {
                    const state = getState(day.key);
                    return (
                      <td
                        aria-selected={selected === day.key}
                        className="flex-1 p-0"
                        data-day={day.key}
                        data-outside={day.outside || undefined}
                        key={day.key}
                      >
                        {day.hidden ? (
                          <div aria-hidden="true" className={styles.cell} />
                        ) : (
                          <CalendarDayButton
                            date={day.key}
                            focused={focus.focusedDate === day.key}
                            labels={labels}
                            loading={Boolean(loading) || !isKnownDay(state)}
                            locale={locale}
                            monthLabel={
                              day.key === overflowFirst
                                ? formatCalendarDate(day.key, locale, {
                                    month: "short",
                                  })
                                : undefined
                            }
                            onBlur={() => focus.onBlur(day.key)}
                            onClick={() => onSelect(day.key)}
                            onFocus={() => focus.onFocus(day.key)}
                            onKeyDown={(event) =>
                              focus.handleKeyDown(event, day.key)
                            }
                            selected={selected === day.key}
                            state={state}
                            tabIndex={focus.target === day.key ? 0 : -1}
                            today={today === day.key}
                            tooltipHandle={
                              day.outside ? tooltipHandle : undefined
                            }
                          />
                        )}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
          <Tooltip disableHoverablePopup handle={tooltipHandle}>
            {({ payload }) => (
              <TooltipPopup
                className="transition-none! **:data-current:opacity-100! **:data-previous:opacity-0! **:data-current:transition-none! **:data-previous:transition-none!"
                portalProps={{
                  className:
                    "**:data-[slot=tooltip-positioner]:transition-none!",
                }}
              >
                {payload}
              </TooltipPopup>
            )}
          </Tooltip>
        </TooltipProvider>
      </div>
    </div>
  );
}

