"use client";

import { UserPlusIcon, XIcon } from "lucide-react";
import type { FormEvent } from "react";
import { useRef, useState } from "react";
import { Button } from "@/registry/default/ui/button";
import { Field, FieldError, FieldLabel } from "@/registry/default/ui/field";
import { Form } from "@/registry/default/ui/form";
import { Group } from "@/registry/default/ui/group";
import { Input } from "@/registry/default/ui/input";
import { Textarea } from "@/registry/default/ui/textarea";
import {
  BookerConfirmation,
  type ConfirmedBooking,
} from "./booker-confirmation";
import type { BookerLabels } from "./booker-labels";
import type { BookerConfirmFormContext } from "./hooks/use-booker";
import { createBookingAction } from "./lib/actions";
import { toCalendarDateKey } from "./lib/booker-utils";
import type { Booking } from "./lib/cal-api/types";
import { getLocationOptionValue, LocationPicker } from "./location";

export type BookerConfirmFormProps = BookerConfirmFormContext & {
  defaultEmail?: string;
  defaultName?: string;
  labels: BookerLabels;
  onSuccess?: (booking: Booking) => void;
  /** For the confirmation screen and its calendar links. */
  eventTitle?: string;
  hostName?: string;
};

function RequiredMark() {
  return <span className="text-destructive-foreground">*</span>;
}

// Cal fills a split name from one string the same way: the first word is the
// first name, the rest the last name.
function splitDefaultName(name?: string): {
  firstName: string;
  lastName: string;
} {
  const [firstName = "", ...rest] = (name ?? "").trim().split(/\s+/);
  return { firstName, lastName: rest.join(" ") };
}

function getDefaultLocationProvider(
  locations: BookerConfirmFormContext["locations"],
): string {
  const location = locations?.[0];
  if (!location) {
    return "";
  }

  return location.provider || getLocationOptionValue(location, 0);
}

export function BookerConfirmForm({
  defaultEmail,
  defaultName,
  eventTitle,
  hostName,
  disableGuests = false,
  durationMinutes,
  includeLengthInMinutes,
  labels,
  locale,
  locations = [],
  onBack,
  onSuccess,
  selectedDate,
  selectedTime,
  splitNameField,
  target,
  timeZone,
}: BookerConfirmFormProps) {
  const nextGuestIdRef = useRef(0);
  const [guestIds, setGuestIds] = useState<number[]>([]);
  const [locationProvider, setLocationProvider] = useState(() =>
    getDefaultLocationProvider(locations),
  );
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [successBooking, setSuccessBooking] = useState<ConfirmedBooking | null>(
    null,
  );

  const resolvedLocationProvider =
    locations.length > 1
      ? locationProvider || getDefaultLocationProvider(locations)
      : getDefaultLocationProvider(locations);

  const handleAddGuest = () => {
    const id = nextGuestIdRef.current;
    nextGuestIdRef.current += 1;
    setGuestIds((current) => [...current, id]);
  };

  const handleRemoveGuest = (id: number) => {
    setGuestIds((current) => current.filter((guestId) => guestId !== id));
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSubmitError(null);

    if (!selectedDate || !selectedTime) {
      setSubmitError(labels.confirmError);
      return;
    }

    const formData = new FormData(event.currentTarget);
    // API v2 takes the attendee's name as one string, so a split name is
    // joined before it is sent.
    const name = splitNameField
      ? [formData.get("firstName"), formData.get("lastName")]
          .map((value) => String(value ?? "").trim())
          .filter(Boolean)
          .join(" ")
      : String(formData.get("name") ?? "").trim();
    const email = String(formData.get("email") ?? "").trim();
    const notes = String(formData.get("notes") ?? "").trim();
    const guests = formData
      .getAll("guests")
      .map((value) => String(value).trim())
      .filter(Boolean);

    if (!name || !email) {
      return;
    }

    setSubmitting(true);

    try {
      const result = await createBookingAction({
        email,
        guests: guests.length > 0 ? guests : undefined,
        ...(includeLengthInMinutes && durationMinutes
          ? { lengthInMinutes: durationMinutes }
          : {}),
        locale,
        locationProvider: resolvedLocationProvider || undefined,
        name,
        notes: notes || undefined,
        selectedDateKey: toCalendarDateKey(selectedDate),
        selectedTime,
        target,
        timeZone,
      });

      if (!result.ok) {
        setSubmitError(result.error || labels.confirmError);
        return;
      }

      setSuccessBooking({
        attendeeEmail: email,
        end: result.booking.end,
        guests,
        hostName: hostName || result.booking.hosts[0]?.name || "",
        location: result.booking.location,
        meetingUrl: result.booking.meetingUrl,
        notes: notes || undefined,
        start: result.booking.start,
        status: result.booking.status,
        title: eventTitle || result.booking.title,
        uid: result.booking.uid,
      });
      onSuccess?.(result.booking);
    } catch {
      setSubmitError(labels.confirmError);
    } finally {
      setSubmitting(false);
    }
  };

  if (successBooking) {
    return <BookerConfirmation booking={successBooking} labels={labels} />;
  }

  return (
    <div className="flex flex-col gap-4">
      <Form className="flex flex-col gap-4" onSubmit={handleSubmit}>
        {splitNameField ? (
          <div className="flex gap-4">
            <Field className="min-w-0 flex-1" name="firstName">
              <FieldLabel>
                {splitNameField.firstNameLabel || labels.confirmFirstName}{" "}
                <RequiredMark />
              </FieldLabel>
              <Input
                autoComplete="given-name"
                autoFocus
                defaultValue={splitDefaultName(defaultName).firstName}
                placeholder={splitNameField.firstNamePlaceholder}
                required
                type="text"
              />
              <FieldError>{labels.confirmFirstNameError}</FieldError>
            </Field>
            <Field className="min-w-0 flex-1" name="lastName">
              <FieldLabel>
                {splitNameField.lastNameLabel || labels.confirmLastName}
                {splitNameField.lastNameRequired ? (
                  <>
                    {" "}
                    <RequiredMark />
                  </>
                ) : null}
              </FieldLabel>
              <Input
                autoComplete="family-name"
                defaultValue={splitDefaultName(defaultName).lastName}
                placeholder={splitNameField.lastNamePlaceholder}
                required={splitNameField.lastNameRequired}
                type="text"
              />
              <FieldError>{labels.confirmLastNameError}</FieldError>
            </Field>
          </div>
        ) : (
          <Field name="name">
            <FieldLabel>
              {labels.confirmYourName} <RequiredMark />
            </FieldLabel>
            <Input autoFocus defaultValue={defaultName} required type="text" />
            <FieldError>{labels.confirmNameError}</FieldError>
          </Field>
        )}

        <Field name="email">
          <FieldLabel>
            {labels.confirmEmail} <RequiredMark />
          </FieldLabel>
          <Input
            autoComplete="email"
            defaultValue={defaultEmail}
            required
            type="email"
          />
          <FieldError>{labels.confirmEmailError}</FieldError>
        </Field>

        <LocationPicker
          label={labels.confirmLocation}
          locations={locations}
          onValueChange={setLocationProvider}
        />

        <Field name="notes">
          <FieldLabel>{labels.confirmNotes}</FieldLabel>
          <Textarea placeholder={labels.confirmNotesPlaceholder} rows={3} />
        </Field>

        {guestIds.length > 0 ? (
          <div className="flex flex-col gap-2">
            {guestIds.map((guestId) => (
              <Group
                key={guestId}
                aria-label={labels.confirmGuestEmail}
                className="w-full gap-2"
              >
                <Input
                  aria-label={labels.confirmGuestEmail}
                  className="flex-1"
                  name="guests"
                  placeholder={labels.confirmGuestEmailPlaceholder}
                  type="email"
                />
                <div>
                  <Button
                    aria-label={labels.confirmRemoveGuest}
                    onClick={() => handleRemoveGuest(guestId)}
                    size="icon"
                    type="button"
                    variant="outline"
                  >
                    <XIcon aria-hidden="true" />
                  </Button>
                </div>
              </Group>
            ))}
          </div>
        ) : null}

        {!disableGuests ? (
          <Button
            className="h-auto! self-start px-0.5"
            onClick={handleAddGuest}
            type="button"
            variant="link"
          >
            <UserPlusIcon aria-hidden="true" />
            {labels.confirmAddGuests}
          </Button>
        ) : null}

        {submitError ? (
          <p className="text-destructive-foreground text-xs" role="alert">
            {submitError}
          </p>
        ) : null}

        <p className="text-muted-foreground text-xs">
          {labels.confirmTermsPrefix}{" "}
          <a
            className="text-foreground underline-offset-4 hover:underline"
            href="https://cal.com/terms"
            rel="noreferrer"
            target="_blank"
          >
            {labels.confirmTerms}
          </a>{" "}
          and{" "}
          <a
            className="text-foreground underline-offset-4 hover:underline"
            href="https://cal.com/privacy"
            rel="noreferrer"
            target="_blank"
          >
            {labels.confirmPrivacyPolicy}
          </a>
          .
        </p>

        <div className="flex justify-end gap-2 pt-1">
          <Button
            disabled={submitting}
            onClick={onBack}
            type="button"
            variant="ghost"
          >
            {labels.confirmBack}
          </Button>
          <Button loading={submitting} type="submit">
            {submitting ? labels.confirmSubmitting : labels.confirmSubmit}
          </Button>
        </div>
      </Form>
    </div>
  );
}

"use client";

// The screen after a booking, as decided in "The confirmation screen"
// (.scratch/booker/issues/09-confirmation-screen.md, variant A, in place):
// it replaces the form in the right pane while the event information stays
// on the left. Status, headline and one sentence; details the left pane
// doesn't show; add to calendar; then cancel and reschedule.
//
// Cancel and reschedule open Cal's own pages for the booking until the
// Booker's own flows ("Reschedule and cancel screens") are built.

import { CalendarPlusIcon, CircleCheckIcon, HourglassIcon } from "lucide-react";
import type { ReactNode } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";
import { bookerHeadingClassName } from "./booker-heading";
import { type BookerLabels, getBookerLabels } from "./booker-labels";

export type ConfirmedBooking = {
  uid: string;
  status: string;
  start: string;
  end: string;
  title: string;
  attendeeEmail: string;
  hostName: string;
  guests: string[];
  notes?: string;
  location?: string | null;
  meetingUrl?: string | null;
};

type ConfirmationLabels = Pick<
  BookerLabels,
  | "confirmedTitle"
  | "confirmedText"
  | "pendingTitle"
  | "pendingText"
  | "confirmationGuests"
  | "confirmationNotes"
  | "addToCalendar"
  | "cancelBooking"
  | "reschedule"
>;

const CAL_APP_URL = "https://app.cal.com";

function toCalendarStamp(iso: string) {
  return new Date(iso)
    .toISOString()
    .replace(/[-:]/g, "")
    .replace(/\.\d{3}/, "");
}

function getCalendarDetails(booking: ConfirmedBooking) {
  return [booking.meetingUrl, booking.notes].filter(Boolean).join("\n\n");
}

/** Built in the browser: the API's calendar-links endpoint needs credentials. */
function getGoogleUrl(booking: ConfirmedBooking) {
  const params = new URLSearchParams({
    action: "TEMPLATE",
    dates: `${toCalendarStamp(booking.start)}/${toCalendarStamp(booking.end)}`,
    details: getCalendarDetails(booking),
    location: booking.meetingUrl ?? booking.location ?? "",
    text: booking.title,
  });
  return `https://calendar.google.com/calendar/render?${params}`;
}

function getOutlookUrl(booking: ConfirmedBooking) {
  const params = new URLSearchParams({
    body: getCalendarDetails(booking),
    enddt: new Date(booking.end).toISOString(),
    location: booking.meetingUrl ?? booking.location ?? "",
    path: "/calendar/action/compose",
    rru: "addevent",
    startdt: new Date(booking.start).toISOString(),
    subject: booking.title,
  });
  return `https://outlook.live.com/calendar/0/deeplink/compose?${params}`;
}

function escapeIcsText(value: string) {
  return value
    .replace(/\\/g, "\\\\")
    .replace(/\n/g, "\\n")
    .replace(/,/g, "\\,")
    .replace(/;/g, "\\;");
}

function getIcsUrl(booking: ConfirmedBooking) {
  const lines = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//coss//Booker//EN",
    "BEGIN:VEVENT",
    `UID:${booking.uid}`,
    `DTSTAMP:${toCalendarStamp(new Date().toISOString())}`,
    `DTSTART:${toCalendarStamp(booking.start)}`,
    `DTEND:${toCalendarStamp(booking.end)}`,
    `SUMMARY:${escapeIcsText(booking.title)}`,
    `DESCRIPTION:${escapeIcsText(getCalendarDetails(booking))}`,
    `LOCATION:${escapeIcsText(booking.meetingUrl ?? booking.location ?? "")}`,
    "END:VEVENT",
    "END:VCALENDAR",
  ];
  return `data:text/calendar;charset=utf-8,${encodeURIComponent(lines.join("\r\n"))}`;
}

function Row({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="flex flex-col gap-1">
      <dt className="text-muted-foreground">{label}</dt>
      <dd>{children}</dd>
    </div>
  );
}

export function BookerConfirmation({
  booking,
  labels: labelOverrides,
}: {
  booking: ConfirmedBooking;
  labels?: Partial<ConfirmationLabels>;
}) {
  const labels: ConfirmationLabels = {
    ...getBookerLabels(),
    ...labelOverrides,
  };
  const pending = booking.status === "pending";
  const calendars = [
    { href: getGoogleUrl(booking), label: "Google" },
    { href: getOutlookUrl(booking), label: "Outlook" },
    {
      download: "booking.ics",
      href: getIcsUrl(booking),
      label: "Apple or other (.ics)",
    },
  ];

  return (
    <div className="flex min-h-64 flex-col gap-6">
      <div className="flex flex-col gap-2">
        {pending ? (
          <HourglassIcon
            aria-hidden="true"
            className="size-6 text-warning-foreground"
          />
        ) : (
          <CircleCheckIcon
            aria-hidden="true"
            className="size-6 text-success-foreground"
          />
        )}
        <h2 className={cn(bookerHeadingClassName, "text-xl")}>
          {pending ? labels.pendingTitle : labels.confirmedTitle}
        </h2>
        <p className="text-muted-foreground sm:text-sm">
          {pending
            ? labels.pendingText(booking.hostName, booking.attendeeEmail)
            : labels.confirmedText(booking.attendeeEmail)}
        </p>
      </div>

      {booking.guests.length > 0 || booking.notes ? (
        <dl className="flex flex-col gap-3 sm:text-sm">
          {booking.guests.length > 0 ? (
            <Row label={labels.confirmationGuests}>
              {booking.guests.join(", ")}
            </Row>
          ) : null}
          {booking.notes ? (
            <Row label={labels.confirmationNotes}>{booking.notes}</Row>
          ) : null}
        </dl>
      ) : null}

      <div className="flex flex-col gap-2">
        <p className="font-medium sm:text-sm">{labels.addToCalendar}</p>
        <div className="flex flex-wrap gap-2">
          {calendars.map((calendar) => (
            <Button
              key={calendar.label}
              render={
                // biome-ignore lint/a11y/useAnchorContent: Button renders the children
                <a
                  download={calendar.download}
                  href={calendar.href}
                  rel="noreferrer"
                  target={calendar.download ? undefined : "_blank"}
                />
              }
              size="sm"
              variant="outline"
            >
              <CalendarPlusIcon aria-hidden="true" />
              {calendar.label}
            </Button>
          ))}
        </div>
      </div>

      <div className="mt-auto flex justify-end gap-2 border-t pt-4">
        <Button
          render={
            // biome-ignore lint/a11y/useAnchorContent: Button renders the children
            <a
              href={`${CAL_APP_URL}/booking/${booking.uid}?cancel=true`}
              rel="noreferrer"
              target="_blank"
            />
          }
          variant="ghost"
        >
          {labels.cancelBooking}
        </Button>
        <Button
          render={
            // biome-ignore lint/a11y/useAnchorContent: Button renders the children
            <a
              href={`${CAL_APP_URL}/reschedule/${booking.uid}`}
              rel="noreferrer"
              target="_blank"
            />
          }
          variant="outline"
        >
          {labels.reschedule}
        </Button>
      </div>
    </div>
  );
}

import { Button } from "@/registry/default/ui/button";
import type { BookerLabels } from "./booker-labels";
import type { BookerError } from "./hooks/use-booker";
import { ResponseCard } from "./response-card";

type BookerErrorStateProps = {
  error: BookerError;
  labels: BookerLabels;
  onRetry: () => void;
};

// The Booker couldn't load: Cal Video's error card (a ResponseCard with an
// error StatusMark), with a retry when trying again can help.
export function BookerErrorState({
  error,
  labels,
  onRetry,
}: BookerErrorStateProps) {
  const isTerminal = error.kind === "not-found" || error.kind === "unpublished";
  const [title, description] =
    error.kind === "unpublished"
      ? [labels.errorUnpublished, labels.errorUnpublishedDescription]
      : error.kind === "not-found"
        ? [labels.errorNotFound, labels.errorNotFoundDescription]
        : error.kind === "network"
          ? [labels.errorNetwork, labels.errorNetworkDescription]
          : [labels.errorGeneric, labels.errorGenericDescription];

  return (
    <div
      className="flex w-full flex-1 items-center justify-center"
      role="alert"
    >
      <ResponseCard
        action={
          isTerminal ? undefined : (
            <Button onClick={onRetry} size="lg">
              {labels.retry}
            </Button>
          )
        }
        description={description}
        status="error"
        title={title}
      />
    </div>
  );
}

