const WINDOW_MONTHS = 3;

export type BookerErrorKind =
  | "not-found"
  | "unpublished"
  | "network"
  | "unknown";

export type BookerError = {
  kind: BookerErrorKind;
  message: string;
};

class BookerDataError extends Error {
  code: string;
  constructor(message: string, code: string) {
    super(message);
    this.code = code;
  }
}

type ResolvedEventType = Extract<
  FetchRawBookerResult,
  { ok: true }
>["resolved"];

export type BookerInitialData = {
  durationMinutes?: number;
  monthIso: string;
  monthsToFetch?: number;
  result: FetchRawBookerResult;
  timeZone: string;
};

type DerivedBookerData = {
  hasMultiDurationOptions: boolean;
  meta: BookerMeta | null;
  minimumBookingNotice: number;
  selectedDurationMinutes: number | null;
};

type HydratedBookerData = DerivedBookerData & {
  coveredMonthKeys: Set<string>;
  error: BookerError | null;
  resolved: ResolvedEventType;
  slotsByDate: Record<string, string[]>;
  slotsCacheKey: string;
};

function classifyError(caught: unknown): BookerError {
  const code = caught instanceof BookerDataError ? caught.code : "";
  const message =
    caught instanceof Error ? caught.message : "Could not load booker data.";

  if (code === "UNPUBLISHED") {
    return { kind: "unpublished", message };
  }
  if (code === "NOT_FOUND") {
    return { kind: "not-found", message };
  }
  if (
    code.startsWith("HTTP_4") ||
    code.startsWith("HTTP_5") ||
    message.includes("fetch") ||
    message.includes("network") ||
    message.includes("ETIMEDOUT") ||
    message.includes("ECONNREFUSED") ||
    /Cal\.com API [45]\d\d/.test(message)
  ) {
    return { kind: "network", message };
  }
  return { kind: "unknown", message };
}

function getTargetIdentity(target: BookerTarget): string {
  if (target.type === "user") {
    return `user:${target.username}:${target.eventSlug}:${target.orgId ?? ""}`;
  }
  if (target.type === "team") {
    return `team:${target.teamId}:${target.eventSlug}:${target.orgId ?? ""}`;
  }
  if (target.type === "dynamic") {
    return `dynamic:${target.usernames.join(",")}:${target.orgSlug ?? ""}:${target.orgId ?? ""}`;
  }
  return `link:${target.bookingUrl}`;
}

function getMonthCacheKey(
  identity: string,
  timeZone: string,
  durationMinutes: number,
  month: Date,
): string {
  return `${identity}|${timeZone}|${durationMinutes}|${month.getFullYear()}-${month.getMonth()}`;
}

function getSlotsCacheKey(
  identity: string,
  timeZone: string,
  durationMinutes: number,
): string {
  return `${identity}|${timeZone}|${durationMinutes}`;
}

// The calendar's date bounds: today or the booking window's start, whichever
// is later, through the window's end.
type CalendarBounds = {
  maxDate?: string;
  minDate: string;
  today: string;
  weekStart: number;
};

function getCalendarBounds(
  todayStart: Date,
  meta: BookerMeta | null | undefined,
): CalendarBounds {
  const today = toCalendarDateKey(todayStart);
  const windowStart = meta?.bookingWindowStart
    ? toCalendarDateKey(meta.bookingWindowStart)
    : undefined;
  return {
    maxDate: meta?.bookingWindowEnd
      ? toCalendarDateKey(meta.bookingWindowEnd)
      : undefined,
    minDate: windowStart && windowStart > today ? windowStart : today,
    today,
    weekStart: meta?.weekStart ?? 0,
  };
}

function getLoadedDayState(
  key: string,
  slotsByDate: Record<string, string[]>,
  today: string,
): CalendarDayState {
  if (key < today) {
    return { available: false };
  }
  return { available: (slotsByDate[key] ?? []).length > 0 };
}

// The selection once a month's availability is known, as the design system:
// kept while it is still visible and selectable, else the first selectable
// day in view.
function resolveSelectedDate(
  month: Date,
  selected: Date | undefined,
  slotsByDate: Record<string, string[]>,
  bounds: CalendarBounds,
): Date | undefined {
  const selectedKey = selected ? toCalendarDateKey(selected) : undefined;
  const key = resolveSelection(
    selectedKey,
    calendarGrid({ ...bounds, month: localDateKey(month).slice(0, 7) }),
    (date) => getLoadedDayState(date, slotsByDate, bounds.today),
  );
  if (!key) {
    return undefined;
  }
  return key === selectedKey ? selected : localDate(key);
}

function deriveBookerData(
  result: Extract<FetchRawBookerResult, { ok: true }>,
  target: BookerTarget,
): DerivedBookerData {
  if (!result.raw.me) {
    return {
      hasMultiDurationOptions: false,
      meta: null,
      minimumBookingNotice: 0,
      selectedDurationMinutes: null,
    };
  }

  const host = extractHost(result.raw.me);
  const isDynamic = Boolean(getDynamicContext(target));
  const hostAvatars = extractHostAvatars(
    result.raw.selectedEventType,
    result.raw.me,
    { dynamic: isDynamic, orgSlug: getOrgSlugFromTarget(target) },
  );
  const hostName = extractHostDisplayName(
    result.raw.selectedEventType,
    result.raw.me,
    { dynamic: isDynamic },
  );
  const eventType = extractEventTypeInfo(result.raw.selectedEventType);
  const minimumBookingNotice = extractMinimumBookingNotice(
    result.raw.selectedEventType,
  );
  const hasMultiDurationOptions =
    (eventType.eventTypeDurationOptions?.length ?? 0) > 1;
  const selectedDurationMinutes =
    eventType.eventTypeDurationOptions?.[0] ??
    eventType.eventTypeDurationMinutes ??
    null;

  return {
    hasMultiDurationOptions,
    meta: {
      bookingWindowEnd: extractBookingWindowEnd(result.raw.selectedEventType),
      bookingWindowStart: extractBookingWindowStart(
        result.raw.selectedEventType,
      ),
      eventTypeDescription: eventType.eventTypeDescription,
      eventTypeDurationMinutes: eventType.eventTypeDurationMinutes,
      eventTypeDurationOptions: eventType.eventTypeDurationOptions,
      eventTypeImageUrl: result.raw.bannerUrl || eventType.eventTypeImageUrl,
      eventTypeLocations: eventType.eventTypeLocations,
      eventTypeTitle: eventType.eventTypeTitle,
      disableGuests: eventType.disableGuests ?? false,
      splitNameField: eventType.splitNameField,
      successRedirectUrl: eventType.successRedirectUrl,
      hostAvatarUrl: host.hostAvatarUrl,
      hostAvatars,
      hostName:
        host.hostName === "Unknown user" && target.type === "user"
          ? target.username
          : result.raw.publicDisplayName || hostName,
      weekStart: extractWeekStart(result.raw.selectedEventType),
    },
    minimumBookingNotice,
    selectedDurationMinutes,
  };
}

function hydrateBookerData({
  initialData,
  selectedTimeZone,
  target,
}: {
  initialData?: BookerInitialData;
  selectedTimeZone: string;
  target: BookerTarget;
}): HydratedBookerData | null {
  if (!initialData) {
    return null;
  }

  if (initialData.timeZone !== selectedTimeZone) {
    return null;
  }

  if (!initialData.result.ok) {
    const error = classifyError(
      new BookerDataError(
        initialData.result.error,
        initialData.result.errorCode ?? "UNKNOWN",
      ),
    );

    if (error.kind !== "not-found" && error.kind !== "unpublished") {
      return null;
    }

    return {
      coveredMonthKeys: new Set(),
      error,
      hasMultiDurationOptions: false,
      meta: null,
      minimumBookingNotice: 0,
      resolved: { eventTypeId: null, eventTypeSlug: null },
      selectedDurationMinutes: null,
      slotsByDate: {},
      slotsCacheKey: "",
    };
  }

  const derived = deriveBookerData(initialData.result, target);
  const durationMinutes =
    derived.selectedDurationMinutes ?? initialData.durationMinutes ?? 30;
  const identity = getTargetIdentity(target);
  const anchor = new Date(initialData.monthIso);
  const safeAnchor = Number.isNaN(anchor.getTime()) ? new Date() : anchor;
  const monthsToFetch = Math.max(
    1,
    Math.floor(initialData.monthsToFetch ?? WINDOW_MONTHS),
  );
  const coveredMonthKeys = new Set<string>();

  for (let offset = 0; offset < monthsToFetch; offset += 1) {
    coveredMonthKeys.add(
      getMonthCacheKey(
        identity,
        selectedTimeZone,
        durationMinutes,
        new Date(safeAnchor.getFullYear(), safeAnchor.getMonth() + offset, 1),
      ),
    );
  }

  const slotsByDate = filterBookableSlots(
    extractSlotsByDate(initialData.result.raw.slots, selectedTimeZone),
    selectedTimeZone,
    derived.minimumBookingNotice,
    new Date(),
  );

  return {
    ...derived,
    coveredMonthKeys,
    error: null,
    resolved: initialData.result.resolved,
    selectedDurationMinutes: durationMinutes,
    slotsByDate,
    slotsCacheKey: getSlotsCacheKey(
      identity,
      selectedTimeZone,
      durationMinutes,
    ),
  };
}

type UseBookerParams = {
  initialData?: BookerInitialData;
  target: BookerTarget;
  timezone?: string;
};

type BookerLoadingState = {
  availability: boolean;
  busy: boolean;
  initial: boolean;
};

type BookerTimezoneState = {
  onValueChange: (timeZone: string) => void;
  value: string;
};

type BookerDurationState = {
  onValueChange: (minutes: number) => void;
  value: number;
};

type BookerCalendarState = Omit<
  BookerCalendarProps,
  "className" | "dir" | "labels" | "locale" | "shiftWeeks"
> & { locale: string };

// What the time list takes. This data layer keeps wall-clock "HH:mm" times
// per day; the list takes the API's instants, so they are converted at this
// edge. The build replaces this data layer (see the map's data-layer
// decision) and keeps the instants throughout.
type BookerTimePickerState = {
  currentMonth: Date;
  empty: TimePickerEmpty;
  is24Hour: boolean;
  loading: "initial" | "refresh" | undefined;
  locale: string;
  onIs24HourChange: (value: boolean) => void;
  onSelect: (start: string) => void;
  onViewFirstAvailability: (() => void) | undefined;
  selectedDate: Date | undefined;
  slots: TimeSlot[];
  timeZone: string;
};

export type BookerStep = "select" | "confirm";

export type BookerConfirmFormContext = {
  disableGuests?: boolean;
  durationMinutes: number;
  includeLengthInMinutes: boolean;
  locale: string;
  locations?: BookerMeta["eventTypeLocations"];
  onBack: () => void;
  splitNameField?: BookerMeta["splitNameField"];
  selectedDate?: Date;
  selectedTime: string | null;
  target: BookerTarget;
  timeZone: string;
};

export type UseBookerResult = {
  calendarProps: BookerCalendarState;
  confirmFormProps: BookerConfirmFormContext;
  durationProps: BookerDurationState;
  error: BookerError | null;
  loadingState: BookerLoadingState;
  meta: BookerMeta | null;
  retry: () => void;
  step: BookerStep;
  timePickerProps: BookerTimePickerState;
  timezoneProps: BookerTimezoneState;
};

// All booker data + interaction logic: fetching/windowing cal.com availability,
// derived selection state, and the handlers the UI wires to the calendar.
export function useBooker({
  initialData,
  target,
  timezone,
}: UseBookerParams): UseBookerResult {
  const [timeZone] = useState(
    () => Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC",
  );
  const [locale] = useState(
    () => Intl.DateTimeFormat().resolvedOptions().locale || "en-US",
  );
  const initialSelectedTimeZone = initialData?.timeZone ?? timezone ?? timeZone;
  const hydratedData = useMemo(
    () =>
      hydrateBookerData({
        initialData,
        selectedTimeZone: initialSelectedTimeZone,
        target,
      }),
    [initialData, initialSelectedTimeZone, target],
  );
  const initialCurrentMonth = useMemo(() => {
    const initialMonth = initialData?.monthIso
      ? new Date(initialData.monthIso)
      : new Date();
    return Number.isNaN(initialMonth.getTime()) ? new Date() : initialMonth;
  }, [initialData?.monthIso]);
  const initialSelectedDate = useMemo(() => {
    if (!hydratedData || hydratedData.error) {
      return undefined;
    }

    return resolveSelectedDate(
      initialCurrentMonth,
      undefined,
      hydratedData.slotsByDate,
      getCalendarBounds(
        getTodayInTimeZone(initialSelectedTimeZone),
        hydratedData.meta,
      ),
    );
  }, [hydratedData, initialCurrentMonth, initialSelectedTimeZone]);
  const [meta, setMeta] = useState<BookerMeta | null>(
    hydratedData?.meta ?? null,
  );
  const [slotsByDate, setSlotsByDate] = useState<Record<string, string[]>>(
    hydratedData?.slotsByDate ?? {},
  );
  const [error, setError] = useState<BookerError | null>(
    hydratedData?.error ?? null,
  );
  const [isPending, setIsPending] = useState(false);
  const [currentMonth, setCurrentMonth] = useState(initialCurrentMonth);
  const [selectedTimeZone, setSelectedTimeZone] = useState(
    initialSelectedTimeZone,
  );
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(
    initialSelectedDate,
  );
  const [_selectedTime, setSelectedTime] = useState<string | null>(null);
  const [step, setStep] = useState<BookerStep>("select");
  const [selectedDurationMinutes, setSelectedDurationMinutes] = useState(
    hydratedData?.selectedDurationMinutes ?? 30,
  );
  const [is24Hour, setIs24Hour] = useState(() => prefers24Hour(locale));
  const coveredMonthsRef = useRef<Set<string>>(
    hydratedData?.coveredMonthKeys ?? new Set(),
  );
  const resolvedRef = useRef<ResolvedEventType>(
    hydratedData?.resolved ?? { eventTypeId: null, eventTypeSlug: null },
  );
  const [_eventTypeId, setEventTypeId] = useState<number | null>(
    hydratedData?.resolved.eventTypeId ?? null,
  );
  const [_eventTypeSlug, setEventTypeSlug] = useState<string | null>(
    hydratedData?.resolved.eventTypeSlug ?? null,
  );
  const lastIdentityRef = useRef<string | null>(null);
  const lastTimeZoneRef = useRef<string | null>(null);
  const lastDurationRef = useRef<number | null>(null);
  const autoSelectedMonthRef = useRef<string | null>(
    initialSelectedDate
      ? `${initialCurrentMonth.getFullYear()}-${initialCurrentMonth.getMonth()}`
      : null,
  );
  const slotsByDateRef = useRef<Record<string, string[]>>(
    hydratedData?.slotsByDate ?? {},
  );
  const slotsCacheRef = useRef<Map<string, Record<string, string[]>>>(
    new Map(
      hydratedData?.slotsCacheKey
        ? [[hydratedData.slotsCacheKey, hydratedData.slotsByDate]]
        : [],
    ),
  );
  const minimumBookingNoticeRef = useRef(
    hydratedData?.minimumBookingNotice ?? 0,
  );
  const hasMultiDurationOptionsRef = useRef(
    hydratedData?.hasMultiDurationOptions ?? false,
  );
  const selectedDateRef = useRef(selectedDate);
  selectedDateRef.current = selectedDate;
  // The latest metadata, also while a load that just set it is still running.
  const metaRef = useRef(meta);
  metaRef.current = meta;
  const inFlightMonthsRef = useRef<Map<string, Promise<void>>>(new Map());
  const availabilityRequestVersionRef = useRef(0);
  const skipInitialWarmRef = useRef(
    Boolean(hydratedData && !hydratedData.error),
  );

  const targetIdentity = useCallback((): string => {
    return getTargetIdentity(target);
  }, [target]);

  const buildKey = useCallback(
    (month: Date) =>
      getMonthCacheKey(
        targetIdentity(),
        selectedTimeZone,
        selectedDurationMinutes,
        month,
      ),
    [selectedDurationMinutes, selectedTimeZone, targetIdentity],
  );

  const slotsCacheKey = useCallback(
    () =>
      getSlotsCacheKey(
        targetIdentity(),
        selectedTimeZone,
        selectedDurationMinutes,
      ),
    [selectedDurationMinutes, selectedTimeZone, targetIdentity],
  );

  const restoreSlotsFromCache = useCallback(() => {
    const cached = slotsCacheRef.current.get(slotsCacheKey()) ?? {};
    slotsByDateRef.current = cached;
    setSlotsByDate(cached);
  }, [slotsCacheKey]);

  useLayoutEffect(() => {
    restoreSlotsFromCache();
  }, [restoreSlotsFromCache]);

  // Fetch a window of several months in a single request, anchored at `anchor`.
  const fetchWindow = useCallback(
    async (anchor: Date): Promise<void> => {
      const anchorKey = buildKey(anchor);

      if (coveredMonthsRef.current.has(anchorKey)) {
        return;
      }

      const existingRequest = inFlightMonthsRef.current.get(anchorKey);
      if (existingRequest) {
        await existingRequest;
        return;
      }

      const requestVersion = availabilityRequestVersionRef.current;
      const windowMonthKeys = Array.from(
        { length: WINDOW_MONTHS },
        (_, offset) =>
          buildKey(
            new Date(anchor.getFullYear(), anchor.getMonth() + offset, 1),
          ),
      );
      const request = (async () => {
        const durationMinutes =
          getDynamicContext(target) || hasMultiDurationOptionsRef.current
            ? selectedDurationMinutes
            : undefined;

        const result = await fetchRawBookerDataAction({
          durationMinutes,
          fetchMeta: resolvedRef.current.eventTypeId == null,
          monthIso: anchor.toISOString(),
          monthsToFetch: WINDOW_MONTHS,
          target,
          timeZone: selectedTimeZone,
          eventTypeId: resolvedRef.current.eventTypeId ?? undefined,
        });

        if (!result.ok) {
          throw new BookerDataError(
            result.error,
            result.errorCode ?? "UNKNOWN",
          );
        }

        if (availabilityRequestVersionRef.current !== requestVersion) {
          return;
        }

        resolvedRef.current = result.resolved;
        setEventTypeId(result.resolved.eventTypeId);
        setEventTypeSlug(result.resolved.eventTypeSlug);

        for (let offset = 0; offset < WINDOW_MONTHS; offset += 1) {
          const month = new Date(
            anchor.getFullYear(),
            anchor.getMonth() + offset,
            1,
          );
          coveredMonthsRef.current.add(buildKey(month));
        }

        // The host/event metadata only comes back on the full (non slots-only)
        // fetch, so set it once when present.
        if (result.raw.me) {
          const derived = deriveBookerData(result, target);
          minimumBookingNoticeRef.current = derived.minimumBookingNotice;
          hasMultiDurationOptionsRef.current = derived.hasMultiDurationOptions;
          metaRef.current = metaRef.current ?? derived.meta;
          setMeta((prev) => prev ?? derived.meta);

          const defaultDuration = derived.selectedDurationMinutes ?? 30;
          if (derived.meta?.eventTypeDurationOptions?.length) {
            if (
              !derived.meta.eventTypeDurationOptions.includes(
                selectedDurationMinutes,
              )
            ) {
              setSelectedDurationMinutes(defaultDuration);
            }
          } else if (
            derived.meta?.eventTypeDurationMinutes != null &&
            selectedDurationMinutes !== derived.meta.eventTypeDurationMinutes
          ) {
            setSelectedDurationMinutes(derived.meta.eventTypeDurationMinutes);
          }
        }

        const windowSlots = filterBookableSlots(
          extractSlotsByDate(result.raw.slots, selectedTimeZone),
          selectedTimeZone,
          minimumBookingNoticeRef.current,
          new Date(),
        );
        const cacheKey = getSlotsCacheKey(
          targetIdentity(),
          selectedTimeZone,
          selectedDurationMinutes,
        );
        const mergedSlots = {
          ...(slotsCacheRef.current.get(cacheKey) ?? {}),
          ...windowSlots,
        };
        slotsCacheRef.current.set(cacheKey, mergedSlots);
        slotsByDateRef.current = mergedSlots;
        setSlotsByDate(mergedSlots);
      })();

      for (const monthKey of windowMonthKeys) {
        inFlightMonthsRef.current.set(monthKey, request);
      }

      try {
        await request;
      } finally {
        for (const monthKey of windowMonthKeys) {
          if (inFlightMonthsRef.current.get(monthKey) === request) {
            inFlightMonthsRef.current.delete(monthKey);
          }
        }
      }
    },
    [
      buildKey,
      selectedDurationMinutes,
      selectedTimeZone,
      target,
      targetIdentity,
    ],
  );

  const todayStart = useMemo(
    () => getTodayInTimeZone(selectedTimeZone),
    [selectedTimeZone],
  );
  const startMonth = useMemo(
    () => getMinimumNavigableMonth(selectedTimeZone, meta?.bookingWindowStart),
    [meta?.bookingWindowStart, selectedTimeZone],
  );
  const calendarBounds = useMemo(
    () => getCalendarBounds(todayStart, meta),
    [meta, todayStart],
  );
  const calendarViewOptions = useMemo((): CalendarViewOptions => {
    return {
      endMonth: meta?.bookingWindowEnd ?? undefined,
      shiftWeeks: true,
      startMonth,
      weekStartsOn: calendarBounds.weekStart,
    };
  }, [calendarBounds.weekStart, meta?.bookingWindowEnd, startMonth]);
  // Revalidates the selection against a month's loaded availability.
  const revalidateSelection = useCallback(
    (month: Date) => {
      const current = selectedDateRef.current;
      const next = resolveSelectedDate(
        month,
        current,
        slotsByDateRef.current,
        getCalendarBounds(
          getTodayInTimeZone(selectedTimeZone),
          metaRef.current,
        ),
      );
      if (next !== current) {
        setSelectedDate(next);
        setSelectedTime(null);
      }
    },
    [selectedTimeZone],
  );

  const hasAvailabilityInView = useMemo(
    () =>
      hasAvailabilityInVisibleGrid(
        currentMonth,
        slotsByDate,
        todayStart,
        calendarViewOptions,
      ),
    [calendarViewOptions, currentMonth, slotsByDate, todayStart],
  );

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      const identity = targetIdentity();
      let deferLoadForMonthSync = false;

      // A different user/event means a different event type and metadata, so
      // reset everything and force a full fetch.
      if (
        lastIdentityRef.current !== null &&
        lastIdentityRef.current !== identity
      ) {
        coveredMonthsRef.current = new Set();
        inFlightMonthsRef.current.clear();
        availabilityRequestVersionRef.current += 1;
        resolvedRef.current = { eventTypeId: null, eventTypeSlug: null };
        setEventTypeId(null);
        setEventTypeSlug(null);
        hasMultiDurationOptionsRef.current = false;
        slotsCacheRef.current = new Map();
        slotsByDateRef.current = {};
        autoSelectedMonthRef.current = null;
        setMeta(null);
        setSelectedDurationMinutes(30);
        setSlotsByDate({});
      } else if (
        lastDurationRef.current !== null &&
        lastDurationRef.current !== selectedDurationMinutes
      ) {
        inFlightMonthsRef.current.clear();
        availabilityRequestVersionRef.current += 1;
        restoreSlotsFromCache();
        autoSelectedMonthRef.current = null;
        setSelectedTime(null);
      } else if (
        lastTimeZoneRef.current !== null &&
        lastTimeZoneRef.current !== selectedTimeZone
      ) {
        coveredMonthsRef.current = new Set();
        inFlightMonthsRef.current.clear();
        availabilityRequestVersionRef.current += 1;
        restoreSlotsFromCache();
        autoSelectedMonthRef.current = null;
        setSelectedTime(null);

        const minMonth = getMinimumNavigableMonth(
          selectedTimeZone,
          meta?.bookingWindowStart,
        );
        if (isCalendarMonthBefore(currentMonth, minMonth)) {
          setCurrentMonth(minMonth);
          deferLoadForMonthSync = true;
        } else {
          const todayInTz = getTodayInTimeZone(selectedTimeZone);
          if (
            selectedDateRef.current &&
            toCalendarDateKey(selectedDateRef.current) <
              toCalendarDateKey(todayInTz)
          ) {
            setSelectedDate(undefined);
          }
        }
      }
      lastIdentityRef.current = identity;
      lastTimeZoneRef.current = selectedTimeZone;
      lastDurationRef.current = selectedDurationMinutes;

      if (deferLoadForMonthSync) {
        return;
      }

      if (!coveredMonthsRef.current.has(buildKey(currentMonth))) {
        setIsPending(true);
        try {
          await fetchWindow(currentMonth);
          if (cancelled) {
            return;
          }
          setError(null);
        } catch (caught) {
          if (cancelled) {
            return;
          }
          setError(classifyError(caught));
          return;
        } finally {
          if (!cancelled) {
            setIsPending(false);
          }
        }
      } else {
        setError(null);
        setIsPending(false);
      }

      // Revalidate the selection the first time this month's availability
      // is known (on load, on month navigation and after a context change):
      // keep it while still selectable, else the first selectable day.
      const monthKey = `${currentMonth.getFullYear()}-${currentMonth.getMonth()}`;
      if (!cancelled && autoSelectedMonthRef.current !== monthKey) {
        autoSelectedMonthRef.current = monthKey;
        revalidateSelection(currentMonth);
      }

      // Warm the next uncovered window boundary, not just the adjacent month.
      // This keeps navigation instant when the user reaches the end of the
      // currently-covered 3-month range.
      const nextWindow = new Date(
        currentMonth.getFullYear(),
        currentMonth.getMonth() + WINDOW_MONTHS,
        1,
      );
      if (skipInitialWarmRef.current) {
        skipInitialWarmRef.current = false;
        return;
      }
      if (!coveredMonthsRef.current.has(buildKey(nextWindow))) {
        void fetchWindow(nextWindow).catch(() => {});
      }
    };

    void load();

    return () => {
      cancelled = true;
    };
  }, [
    buildKey,
    currentMonth,
    fetchWindow,
    selectedDurationMinutes,
    selectedTimeZone,
    meta?.bookingWindowStart,
    revalidateSelection,
    restoreSlotsFromCache,
    targetIdentity,
  ]);

  const [retryCounter, setRetryCounter] = useState(0);

  const retry = useCallback(() => {
    coveredMonthsRef.current = new Set();
    inFlightMonthsRef.current.clear();
    availabilityRequestVersionRef.current += 1;
    slotsCacheRef.current = new Map();
    slotsByDateRef.current = {};
    autoSelectedMonthRef.current = null;
    setSlotsByDate({});
    setError(null);
    setRetryCounter((c) => c + 1);
  }, []);

  // Re-trigger the main load effect when the user retries.
  useEffect(() => {
    // The first render (retryCounter === 0) is handled by the main effect.
    if (retryCounter === 0) return;
    setIsPending(true);
    let cancelled = false;

    (async () => {
      try {
        await fetchWindow(currentMonth);
        if (cancelled) return;
        setError(null);

        const monthKey = `${currentMonth.getFullYear()}-${currentMonth.getMonth()}`;
        if (autoSelectedMonthRef.current !== monthKey) {
          autoSelectedMonthRef.current = monthKey;
          revalidateSelection(currentMonth);
        }
      } catch (caught) {
        if (cancelled) return;
        setError(classifyError(caught));
      } finally {
        if (!cancelled) setIsPending(false);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [retryCounter, fetchWindow, currentMonth, revalidateSelection]);

  useEffect(() => {
    if (!timezone) {
      return;
    }
    setSelectedTimeZone(timezone);
  }, [timezone]);

  const selectedDateKey = toCalendarDateKey(selectedDate ?? todayStart);
  const daySlots =
    selectedDate != null ? (slotsByDate[selectedDateKey] ?? []) : [];
  const nextAvailableDate = findNextAvailableDate(
    slotsByDate,
    selectedTimeZone,
    todayStart,
  );

  // `preserveSelection` comes from keyboard moves: focus changed month, the
  // selection stays.
  const handleMonthChange = (nextMonth: string, preserveSelection = false) => {
    const month = localDate(`${nextMonth}-01`);
    const monthKey = `${month.getFullYear()}-${month.getMonth()}`;
    const monthCovered = coveredMonthsRef.current.has(buildKey(month));
    setCurrentMonth(month);
    // Flip to pending in the same render as the month change when the target
    // month still needs fetching, so the skeleton shows immediately instead of
    // the empty state flashing for a frame before the async effect runs.
    if (!monthCovered) {
      setIsPending(true);
    }
    if (preserveSelection) {
      autoSelectedMonthRef.current = monthKey;
      return;
    }
    setSelectedTime(null);
    // For an already-loaded month, revalidate the selection in the same
    // update as the month change so it doesn't flicker; otherwise once the
    // month loads.
    if (monthCovered) {
      autoSelectedMonthRef.current = monthKey;
      revalidateSelection(month);
    }
  };

  // Selecting the selected day keeps it; an overflow day keeps the displayed
  // month.
  const handleSelectDate = (key: string) => {
    setSelectedDate(localDate(key));
    setSelectedTime(null);
    autoSelectedMonthRef.current = `${currentMonth.getFullYear()}-${currentMonth.getMonth()}`;
  };

  const getDay = (key: string): CalendarDayState => {
    if (
      key >= calendarBounds.today &&
      !coveredMonthsRef.current.has(buildKey(localDate(key)))
    ) {
      return { available: "unknown" };
    }
    return getLoadedDayState(key, slotsByDate, calendarBounds.today);
  };

  const goToDate = (date: Date) => {
    setCurrentMonth(date);
    setSelectedDate(date);
    setSelectedTime(null);
    autoSelectedMonthRef.current = `${date.getFullYear()}-${date.getMonth()}`;
  };

  const handleSelectTime = (time: string) => {
    setSelectedTime(time);
    setStep("confirm");
  };

  const handleBack = useCallback(() => {
    setStep("select");
  }, []);

  const initialLoading = !meta;
  const currentMonthCovered = coveredMonthsRef.current.has(
    buildKey(currentMonth),
  );
  const availabilityLoading = isPending || !currentMonthCovered;

  const confirmFormProps = useMemo((): BookerConfirmFormContext => {
    return {
      disableGuests: meta?.disableGuests,
      durationMinutes: selectedDurationMinutes,
      includeLengthInMinutes: (meta?.eventTypeDurationOptions?.length ?? 0) > 1,
      locale,
      locations: meta?.eventTypeLocations,
      onBack: handleBack,
      selectedDate,
      selectedTime: _selectedTime,
      splitNameField: meta?.splitNameField,
      target,
      timeZone: selectedTimeZone,
    };
  }, [
    _selectedTime,
    locale,
    meta?.disableGuests,
    meta?.eventTypeDurationOptions,
    meta?.eventTypeLocations,
    meta?.splitNameField,
    selectedDate,
    selectedDurationMinutes,
    selectedTimeZone,
    target,
    handleBack,
  ]);

  return {
    calendarProps: {
      getDay,
      loading: initialLoading
        ? "initial"
        : availabilityLoading
          ? "availability"
          : undefined,
      locale,
      maxDate: calendarBounds.maxDate,
      minDate: calendarBounds.minDate,
      month: localDateKey(currentMonth).slice(0, 7),
      onMonthChange: handleMonthChange,
      onSelect: handleSelectDate,
      selected: selectedDate ? toCalendarDateKey(selectedDate) : undefined,
      today: calendarBounds.today,
      weekStart: calendarBounds.weekStart,
    },
    confirmFormProps,
    durationProps: {
      onValueChange: setSelectedDurationMinutes,
      value: selectedDurationMinutes,
    },
    error,
    loadingState: {
      availability: availabilityLoading,
      busy: initialLoading || availabilityLoading,
      initial: initialLoading,
    },
    meta,
    retry,
    step,
    timePickerProps: {
      currentMonth,
      empty: nextAvailableDate || hasAvailabilityInView ? "day" : "range",
      is24Hour,
      loading: initialLoading
        ? "initial"
        : availabilityLoading
          ? "refresh"
          : undefined,
      locale,
      onIs24HourChange: setIs24Hour,
      onSelect: (start) =>
        handleSelectTime(toTimeLabel(new Date(start), selectedTimeZone)),
      onViewFirstAvailability: nextAvailableDate
        ? () => goToDate(nextAvailableDate)
        : undefined,
      selectedDate,
      slots: daySlots.map((time) => ({
        start: buildBookingStartIso(selectedDateKey, time, selectedTimeZone),
      })),
      timeZone: selectedTimeZone,
    },
    timezoneProps: {
      onValueChange: setSelectedTimeZone,
      value: selectedTimeZone,
    },
  };
}

"use server";

import { buildBookingStartIso } from "./booker-utils";
import { toBookingLocation } from "./booking-location";
import { createBooking } from "./cal-api/bookings";
import { CalApiError } from "./cal-api/client";
import {
  getDynamicEventType,
  getEventType,
  getEventTypeById,
  getTeamEventType,
  getTeamSlugEventType,
} from "./cal-api/event-types";
import { getPublicEventInfo } from "./cal-api/public-event";
import { getAvailableSlots } from "./cal-api/slots";
import type { Booking, EventType } from "./cal-api/types";
import {
  type BookerTarget,
  getCreateBookingParamsFromTarget,
  getDynamicContext,
  getOrgSlugFromTarget,
  getPublicEventBannerParamsFromTarget,
  getUserSlotParamsFromTarget,
  parseBookingUrlTarget,
} from "./target";

export type FetchRawBookerInput = {
  monthIso: string;
  timeZone: string;
  target: BookerTarget;
  monthsToFetch?: number;
  eventTypeId?: number;
  fetchMeta?: boolean;
  durationMinutes?: number;
};

type ResolvedEventType = {
  eventTypeId: number | null;
  eventTypeSlug: string | null;
  dynamic?: {
    orgId?: number;
    orgSlug?: string;
    usernames: string[];
  };
};

export type FetchRawBookerResult =
  | {
      ok: true;
      raw: {
        me: unknown;
        eventTypes: unknown;
        selectedEventType: unknown | null;
        bannerUrl: string;
        publicDisplayName: string;
        slots: unknown;
      };
      resolved: ResolvedEventType;
    }
  | {
      ok: false;
      error: string;
      errorCode?: string;
    };

function buildMePayload(target: BookerTarget, eventType: EventType): unknown {
  const owner = eventType.users?.[0] ?? eventType.hosts?.[0];
  const dynamicContext = getDynamicContext(target);
  const fallbackName =
    target.type === "user"
      ? target.username
      : dynamicContext
        ? dynamicContext.usernames.join(" + ")
        : (owner?.username ?? "Unknown user");

  return {
    data: {
      avatarUrl: owner?.avatarUrl,
      name: owner?.name ?? fallbackName,
      username: owner?.username ?? fallbackName,
    },
  };
}

function buildSlotRange(monthIso: string, monthsToFetch: number) {
  const monthDate = new Date(monthIso);
  const safeMonthDate = Number.isNaN(monthDate.getTime())
    ? new Date()
    : monthDate;
  const monthStart = new Date(
    Date.UTC(safeMonthDate.getFullYear(), safeMonthDate.getMonth(), 1),
  );
  const rangeEnd = new Date(
    Date.UTC(
      safeMonthDate.getFullYear(),
      safeMonthDate.getMonth() + monthsToFetch,
      0,
    ),
  );
  const now = new Date();
  const todayUtc = new Date(
    Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()),
  );
  const rangeStart = monthStart < todayUtc ? todayUtc : monthStart;

  return {
    end: rangeEnd.toISOString().slice(0, 10),
    start: rangeStart.toISOString().slice(0, 10),
  };
}

async function fetchSlotsForEventType(
  input: FetchRawBookerInput,
  resolved: ResolvedEventType,
): Promise<unknown> {
  const monthsToFetch = Math.max(1, Math.floor(input.monthsToFetch ?? 1));
  const { end, start } = buildSlotRange(input.monthIso, monthsToFetch);
  const duration = input.durationMinutes;
  const organizationSlug = getOrgSlugFromTarget(input.target);
  const userSlotParams = getUserSlotParamsFromTarget(input.target);

  if (resolved.dynamic) {
    return getAvailableSlots({
      duration,
      end,
      organizationSlug: resolved.dynamic.orgSlug,
      start,
      timeZone: input.timeZone,
      usernames: resolved.dynamic.usernames,
    });
  }

  // Org-hosted user events (e.g. i.cal.com/pasquale/15min) need organizationSlug
  // on the slots request; username + slug alone resolve a different availability.
  if (organizationSlug && userSlotParams) {
    return getAvailableSlots({
      duration,
      end,
      eventTypeSlug: userSlotParams.eventTypeSlug,
      organizationSlug,
      start,
      timeZone: input.timeZone,
      username: userSlotParams.username,
    });
  }

  if (resolved.eventTypeId != null) {
    return getAvailableSlots({
      duration,
      end,
      eventTypeId: resolved.eventTypeId,
      organizationSlug,
      start,
      timeZone: input.timeZone,
    });
  }

  const eventTypeSlug = resolved.eventTypeSlug;
  if (!eventTypeSlug) {
    throw new CalApiError(
      "Missing event type slug for slot lookup.",
      "MISSING_SLUG",
      400,
    );
  }

  return getAvailableSlots({
    duration,
    end,
    eventTypeSlug,
    organizationSlug,
    start,
    timeZone: input.timeZone,
    username: userSlotParams?.username,
  });
}

async function fetchPublicEventInfo(
  target: BookerTarget,
): Promise<{ bannerUrl: string; displayName: string }> {
  const params = getPublicEventBannerParamsFromTarget(target);
  if (!params) {
    return { bannerUrl: "", displayName: "" };
  }

  return getPublicEventInfo(params);
}

function getHeaderBannerUrl(
  target: BookerTarget,
  publicInfo: { bannerUrl: string },
): string {
  // Cal's public booker does not show the org/team banner for dynamic bookings.
  if (getDynamicContext(target)) {
    return "";
  }

  return publicInfo.bannerUrl;
}

async function resolveEventType(
  target: BookerTarget,
): Promise<EventType | null> {
  if (target.type === "dynamic") {
    return getDynamicEventType({
      orgId: target.orgId,
      orgSlug: target.orgSlug,
      usernames: target.usernames,
    });
  }

  if (target.type === "user") {
    return getEventType({
      eventSlug: target.eventSlug,
      orgId: target.orgId,
      username: target.username,
    });
  }

  if (target.type === "team") {
    return getTeamEventType({
      eventSlug: target.eventSlug,
      orgId: target.orgId,
      teamId: target.teamId,
    });
  }

  const parsed = parseBookingUrlTarget(target.bookingUrl, target.orgId);
  if (parsed.type === "dynamic") {
    return getDynamicEventType({
      orgId: parsed.orgId,
      orgSlug: parsed.orgSlug,
      usernames: parsed.usernames,
    });
  }

  if (parsed.type === "user") {
    return getEventType({
      eventSlug: parsed.eventSlug,
      orgId: parsed.orgId,
      orgSlug: parsed.orgSlug,
      username: parsed.username,
    });
  }

  return getTeamSlugEventType({
    eventSlug: parsed.eventSlug,
    orgId: parsed.orgId,
    orgSlug: parsed.orgSlug,
    teamSlug: parsed.teamSlug,
  });
}

function buildResolvedEventType(
  target: BookerTarget,
  selectedEventType: EventType,
): ResolvedEventType {
  const dynamic = getDynamicContext(target);
  if (dynamic) {
    return { dynamic, eventTypeId: null, eventTypeSlug: null };
  }

  return {
    eventTypeId: selectedEventType.id > 0 ? selectedEventType.id : null,
    eventTypeSlug: selectedEventType.slug,
  };
}

export async function fetchRawBookerDataAction(
  input: FetchRawBookerInput,
): Promise<FetchRawBookerResult> {
  try {
    if (input.eventTypeId != null) {
      const resolved: ResolvedEventType = {
        eventTypeId: input.eventTypeId,
        eventTypeSlug: null,
      };
      const slots = await fetchSlotsForEventType(input, resolved);

      if (!input.fetchMeta) {
        return {
          ok: true,
          raw: {
            bannerUrl: "",
            eventTypes: null,
            me: null,
            publicDisplayName: "",
            selectedEventType: null,
            slots,
          },
          resolved,
        };
      }

      const [selectedEventType, publicInfo] = await Promise.all([
        getEventTypeById(input.eventTypeId),
        fetchPublicEventInfo(input.target),
      ]);

      return {
        ok: true,
        raw: {
          bannerUrl: getHeaderBannerUrl(input.target, publicInfo),
          eventTypes: [selectedEventType],
          me: buildMePayload(input.target, selectedEventType),
          publicDisplayName: publicInfo.displayName,
          selectedEventType,
          slots,
        },
        resolved,
      };
    }

    const selectedEventType = await resolveEventType(input.target);

    if (!selectedEventType) {
      return {
        error: "No event type found for the provided target.",
        errorCode: "NOT_FOUND",
        ok: false,
      };
    }

    if (selectedEventType.hidden) {
      return {
        error:
          "This event type is currently unpublished and not accepting bookings.",
        errorCode: "UNPUBLISHED",
        ok: false,
      };
    }

    const resolved = buildResolvedEventType(input.target, selectedEventType);
    const [slots, publicInfo] = await Promise.all([
      fetchSlotsForEventType(input, resolved),
      fetchPublicEventInfo(input.target),
    ]);

    return {
      ok: true,
      raw: {
        bannerUrl: getHeaderBannerUrl(input.target, publicInfo),
        eventTypes: [selectedEventType],
        me: buildMePayload(input.target, selectedEventType),
        publicDisplayName: publicInfo.displayName,
        selectedEventType,
        slots,
      },
      resolved,
    };
  } catch (error) {
    if (error instanceof CalApiError) {
      return {
        error: error.message,
        errorCode: error.code,
        ok: false,
      };
    }
    return {
      error:
        error instanceof Error ? error.message : "Could not load booker data.",
      ok: false,
    };
  }
}

export type CreateBookingActionInput = {
  email: string;
  guests?: string[];
  lengthInMinutes?: number;
  locale?: string;
  locationProvider?: string;
  name: string;
  notes?: string;
  selectedDateKey: string;
  selectedTime: string;
  target: BookerTarget;
  timeZone: string;
};

export type CreateBookingActionResult =
  | { ok: true; booking: Booking }
  | { ok: false; error: string; errorCode?: string };

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validateCreateBookingInput(
  input: CreateBookingActionInput,
): CreateBookingActionResult | null {
  const name = input.name.trim();
  if (!name) {
    return {
      error: "Name is required.",
      errorCode: "INVALID_NAME",
      ok: false,
    };
  }

  const email = input.email.trim();
  if (!email || !EMAIL_PATTERN.test(email)) {
    return {
      error: "A valid email address is required.",
      errorCode: "INVALID_EMAIL",
      ok: false,
    };
  }

  if (!/^\d{4}-\d{2}-\d{2}$/.test(input.selectedDateKey)) {
    return {
      error: "Invalid booking date.",
      errorCode: "INVALID_DATE",
      ok: false,
    };
  }

  if (!/^\d{2}:\d{2}$/.test(input.selectedTime)) {
    return {
      error: "Invalid booking time.",
      errorCode: "INVALID_TIME",
      ok: false,
    };
  }

  if (!input.timeZone.trim()) {
    return {
      error: "Timezone is required.",
      errorCode: "INVALID_TIMEZONE",
      ok: false,
    };
  }

  if (input.guests?.some((guest) => !EMAIL_PATTERN.test(guest.trim()))) {
    return {
      error: "All guest emails must be valid.",
      errorCode: "INVALID_GUEST_EMAIL",
      ok: false,
    };
  }

  return null;
}

function getEventTypeDurationOptions(eventType: EventType): number[] | null {
  const options = (
    eventType as EventType & { lengthInMinutesOptions?: number[] }
  ).lengthInMinutesOptions;
  if (!Array.isArray(options)) {
    return null;
  }

  const parsed = options.filter(
    (value): value is number => typeof value === "number" && value > 0,
  );
  return parsed.length > 1 ? parsed : null;
}

function resolveBookingLengthInMinutes(
  eventType: EventType,
  lengthInMinutes: number | undefined,
): CreateBookingActionResult | { lengthInMinutes?: number } {
  const durationOptions = getEventTypeDurationOptions(eventType);
  if (!durationOptions) {
    return {};
  }

  if (lengthInMinutes == null) {
    return {
      error: "Duration is required for this event type.",
      errorCode: "INVALID_DURATION",
      ok: false,
    };
  }

  if (!durationOptions.includes(lengthInMinutes)) {
    return {
      error: "The selected duration is not allowed for this event type.",
      errorCode: "INVALID_DURATION",
      ok: false,
    };
  }

  return { lengthInMinutes };
}

async function resolveBookableEventType(
  target: BookerTarget,
): Promise<CreateBookingActionResult | { eventType: EventType }> {
  const eventType = await resolveEventType(target);

  if (!eventType) {
    return {
      error: "No event type found for the provided target.",
      errorCode: "NOT_FOUND",
      ok: false,
    };
  }

  if (eventType.hidden) {
    return {
      error:
        "This event type is not currently published and is not accepting bookings.",
      errorCode: "UNPUBLISHED",
      ok: false,
    };
  }

  return { eventType };
}

export async function createBookingAction(
  input: CreateBookingActionInput,
): Promise<CreateBookingActionResult> {
  try {
    const validationError = validateCreateBookingInput(input);
    if (validationError) {
      return validationError;
    }

    const resolvedEvent = await resolveBookableEventType(input.target);
    if (!("eventType" in resolvedEvent)) {
      return resolvedEvent;
    }

    const { eventType } = resolvedEvent;

    if (eventType.disableGuests && input.guests?.length) {
      return {
        error: "Guests are not allowed for this event type.",
        errorCode: "GUESTS_DISABLED",
        ok: false,
      };
    }

    const lengthResult = resolveBookingLengthInMinutes(
      eventType,
      input.lengthInMinutes,
    );
    if ("ok" in lengthResult) {
      return lengthResult;
    }

    const start = buildBookingStartIso(
      input.selectedDateKey,
      input.selectedTime,
      input.timeZone,
    );
    const bookingFieldsResponses: Record<string, unknown> = {};

    if (input.notes?.trim()) {
      bookingFieldsResponses.notes = input.notes.trim();
    }

    if (input.locationProvider?.trim()) {
      bookingFieldsResponses.location = input.locationProvider.trim();
    }

    const targetParams = getCreateBookingParamsFromTarget(input.target, {
      eventTypeSlug: eventType.slug,
    });

    const body: Parameters<typeof createBooking>[0] = {
      attendee: {
        email: input.email.trim(),
        name: input.name.trim(),
        timeZone: input.timeZone,
        ...(input.locale ? { language: input.locale.split("-")[0] } : {}),
      },
      start,
      ...(input.guests?.length ? { guests: input.guests } : {}),
      ...(Object.keys(bookingFieldsResponses).length
        ? { bookingFieldsResponses }
        : {}),
      ...("lengthInMinutes" in lengthResult && lengthResult.lengthInMinutes
        ? { lengthInMinutes: lengthResult.lengthInMinutes }
        : {}),
    };

    if (eventType.id > 0) {
      body.eventTypeId = eventType.id;
    } else if (
      eventType.slug &&
      (targetParams.username || targetParams.teamSlug)
    ) {
      body.eventTypeSlug = eventType.slug;
      if (targetParams.username) {
        body.username = targetParams.username;
      }
      if (targetParams.teamSlug) {
        body.teamSlug = targetParams.teamSlug;
      }
      if (targetParams.organizationSlug) {
        body.organizationSlug = targetParams.organizationSlug;
      }
    } else {
      return {
        error: "Missing event type for booking.",
        errorCode: "MISSING_EVENT_TYPE",
        ok: false,
      };
    }

    if (input.locationProvider?.trim()) {
      body.location = toBookingLocation(input.locationProvider.trim());
    }

    const booking = await createBooking(body);
    return { ok: true, booking };
  } catch (error) {
    if (error instanceof CalApiError) {
      return {
        error: error.message,
        errorCode: error.code,
        ok: false,
      };
    }

    return {
      error:
        error instanceof Error ? error.message : "Could not create booking.",
      ok: false,
    };
  }
}

import { toWeekStart } from "../booker-calendar-model";

export type EventTypeLocationOption = {
  label: string;
  provider: string;
};

/**
 * The host's name question when it is split into first and last name
 * (`type: "splitName"` in event types `2024-06-14`). Labels and placeholders
 * are the host's own; empty means Cal's defaults.
 */
export type BookerSplitNameField = {
  firstNameLabel?: string;
  firstNamePlaceholder?: string;
  lastNameLabel?: string;
  lastNamePlaceholder?: string;
  lastNameRequired: boolean;
};

export type BookerAvatar = {
  name: string;
  avatarUrl: string;
  profileUrl: string;
};

export type BookerMeta = {
  hostName: string;
  hostAvatarUrl: string;
  hostAvatars: BookerAvatar[];
  eventTypeTitle: string;
  eventTypeDescription: string;
  eventTypeDurationMinutes: number | null;
  eventTypeDurationOptions: number[] | null;
  eventTypeLocations: EventTypeLocationOption[];
  eventTypeImageUrl: string;
  disableGuests: boolean;
  splitNameField?: BookerSplitNameField;
  successRedirectUrl?: string;
  bookingWindowStart: Date | null;
  bookingWindowEnd: Date | null;
  /** First day of the week, 0 = Sunday … 6 = Saturday. */
  weekStart: number;
};

export type EventTypeInfo = {
  eventTypeTitle: string;
  eventTypeDescription: string;
  eventTypeDurationMinutes: number | null;
  eventTypeDurationOptions: number[] | null;
  eventTypeLocations: EventTypeLocationOption[];
  eventTypeImageUrl: string;
  disableGuests?: boolean;
  splitNameField?: BookerSplitNameField;
  /** The host's address to send the attendee to after a booking. */
  successRedirectUrl?: string;
};

export function prettifyLocation(value: string): string {
  const normalized = value.trim().toLowerCase();

  const known: Record<string, string> = {
    "cal-video": "Cal Video",
    "daily-video": "Daily Video",
    "google-meet": "Google Meet",
    "huddle01-video": "Huddle01",
    "microsoft-teams": "Microsoft Teams",
    conferencing: "Organizer's Default App",
    jitsi: "Jitsi Meet",
    inperson: "In person",
    organizersdefaultapp: "Organizer's Default App",
    phone: "Phone call",
    whereby: "Whereby",
    zoom: "Zoom",
  };

  const knownLocation = known[normalized];
  if (knownLocation) {
    return knownLocation;
  }

  return titleizeLocation(value);
}

function titleizeLocation(value: string): string {
  return value
    .replace(/[_:-]+/g, " ")
    .split(" ")
    .filter(Boolean)
    .map((part) =>
      /^\d+$/.test(part) ? part : part.charAt(0).toUpperCase() + part.slice(1),
    )
    .join(" ");
}

function normalizeAvatarUrl(value: unknown): string {
  if (typeof value !== "string") {
    return "";
  }

  const trimmed = value.trim();
  if (!trimmed) {
    return "";
  }

  if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) {
    return trimmed;
  }

  if (trimmed.startsWith("//")) {
    return `https:${trimmed}`;
  }

  if (trimmed.startsWith("/")) {
    return `https://app.cal.com${trimmed}`;
  }

  return trimmed;
}

export function extractHost(payload: unknown): {
  hostName: string;
  hostAvatarUrl: string;
} {
  if (!payload || typeof payload !== "object") {
    return { hostName: "Unknown user", hostAvatarUrl: "" };
  }

  const root = payload as Record<string, unknown>;
  const data = (root.data as Record<string, unknown> | undefined) ?? root;
  const profile =
    data.profile && typeof data.profile === "object"
      ? (data.profile as Record<string, unknown>)
      : undefined;

  const rawAvatar =
    data.avatarUrl ??
    data.avatar_url ??
    data.avatar ??
    profile?.avatarUrl ??
    profile?.avatar_url ??
    profile?.avatar;

  return {
    hostName: String(
      data.name ?? data.username ?? data.email ?? "Unknown user",
    ),
    hostAvatarUrl: normalizeAvatarUrl(rawAvatar),
  };
}

function toRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object"
    ? (value as Record<string, unknown>)
    : null;
}

function getAvatarName(record: Record<string, unknown>): string {
  return String(
    record.name ?? record.username ?? record.email ?? "Unknown user",
  );
}

function getAvatarUrl(record: Record<string, unknown>): string {
  const profile = toRecord(record.profile);
  return normalizeAvatarUrl(
    record.avatarUrl ??
      record.avatar_url ??
      record.avatar ??
      record.image ??
      record.logoUrl ??
      profile?.avatarUrl ??
      profile?.avatar_url ??
      profile?.avatar ??
      profile?.image,
  );
}

function buildProfileUrl(
  username: string,
  orgSlug?: string,
  baseUrl?: string,
): string {
  const normalizedUsername = username.trim();
  if (!normalizedUsername) {
    return "";
  }

  const base =
    baseUrl && /^https?:\/\//i.test(baseUrl)
      ? baseUrl.replace(/\/$/, "")
      : orgSlug
        ? `https://${orgSlug}.cal.com`
        : "https://cal.com";

  return `${base}/${encodeURIComponent(normalizedUsername)}`;
}

function getUserAvatar(
  record: Record<string, unknown>,
  orgSlug?: string,
): BookerAvatar {
  const name = getAvatarName(record);
  const username = getStringValue(record.username);
  const bookerUrl = getStringValue(record.bookerUrl);

  return {
    avatarUrl: getAvatarUrl(record),
    name,
    profileUrl: username
      ? buildProfileUrl(username, orgSlug, bookerUrl ?? undefined)
      : "",
  };
}

function getTeamAvatar(
  record: Record<string, unknown>,
  orgSlug?: string,
): BookerAvatar | null {
  const team = toRecord(record.team) ?? toRecord(record.entity);
  const profile = toRecord(record.profile);
  const source = team ?? profile;
  if (!source) {
    return null;
  }

  const avatarUrl = getAvatarUrl(source);
  const name = String(source.name ?? source.slug ?? "");
  const slug = getStringValue(source.slug);
  if (!avatarUrl && !name) {
    return null;
  }

  return {
    avatarUrl,
    name: name || "Team",
    profileUrl: slug ? buildProfileUrl(slug, orgSlug) : "",
  };
}

function getBooleanValue(value: unknown): boolean {
  return value === true || value === "true";
}

function uniqueAvatars(avatars: BookerAvatar[]): BookerAvatar[] {
  const seen = new Set<string>();
  return avatars.filter((avatar) => {
    const key = `${avatar.name}:${avatar.avatarUrl}`;
    if (seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

export function extractHostAvatars(
  eventTypePayload: unknown,
  hostPayload: unknown,
  options: { dynamic?: boolean; orgSlug?: string } = {},
): BookerAvatar[] {
  const eventType = toRecord(eventTypePayload);
  const host = extractHost(hostPayload);

  if (!eventType) {
    return host.hostName === "Unknown user" && !host.hostAvatarUrl
      ? []
      : [
          {
            avatarUrl: host.hostAvatarUrl,
            name: host.hostName,
            profileUrl: "",
          },
        ];
  }

  const schedulingType = String(eventType.schedulingType ?? "").toUpperCase();
  const metadata = toRecord(eventType.metadata);
  const roundRobinHideOrgAndTeam =
    getBooleanValue(eventType.roundRobinHideOrgAndTeam) ||
    getBooleanValue(metadata?.roundRobinHideOrgAndTeam);
  const hideOrgTeamAvatar =
    getBooleanValue(eventType.hideOrgTeamAvatar) ||
    getBooleanValue(metadata?.hideOrgTeamAvatar);
  const userRecords = [
    ...(Array.isArray(eventType.users) ? eventType.users : []),
    ...(Array.isArray(eventType.hosts) ? eventType.hosts : []),
  ]
    .map(toRecord)
    .filter((record): record is Record<string, unknown> => record != null);
  const userAvatars = userRecords.map((record) =>
    getUserAvatar(record, options.orgSlug),
  );
  const teamAvatar = getTeamAvatar(eventType, options.orgSlug);

  if (options.dynamic) {
    return uniqueAvatars(
      userAvatars.length > 0
        ? userAvatars
        : [
            {
              avatarUrl: host.hostAvatarUrl,
              name: host.hostName,
              profileUrl: "",
            },
          ],
    );
  }

  if (schedulingType === "ROUND_ROBIN") {
    if (roundRobinHideOrgAndTeam || hideOrgTeamAvatar) {
      return [];
    }

    return teamAvatar ? [teamAvatar] : [];
  }

  if (schedulingType === "COLLECTIVE") {
    const avatars = teamAvatar ? [teamAvatar, ...userAvatars] : userAvatars;
    return uniqueAvatars(avatars);
  }

  const firstUserAvatar = userAvatars[0];
  return uniqueAvatars(
    firstUserAvatar
      ? [firstUserAvatar]
      : [
          {
            avatarUrl: host.hostAvatarUrl,
            name: host.hostName,
            profileUrl: "",
          },
        ],
  );
}

/**
 * The design system's host identity label: one name, or the first and how
 * many others ("Alex Rivera and 5 others").
 */
export function getHostIdentityLabel(names: string[], fallback: string) {
  const first = names[0];
  if (!first) {
    return fallback;
  }
  if (names.length === 1) {
    return first;
  }
  const rest = names.length - 1;
  return `${first} and ${rest} ${rest === 1 ? "other" : "others"}`;
}

export function extractHostDisplayName(
  eventTypePayload: unknown,
  hostPayload: unknown,
  options: { dynamic?: boolean } = {},
): string {
  const host = extractHost(hostPayload);
  const eventType = toRecord(eventTypePayload);
  if (!eventType) {
    return host.hostName;
  }

  const schedulingType = String(eventType.schedulingType ?? "").toUpperCase();
  const profile = toRecord(eventType.profile);
  const team = toRecord(eventType.team) ?? toRecord(eventType.entity);
  const profileName =
    getStringValue(profile?.name) ?? getStringValue(team?.name);
  const userNames = [
    ...(Array.isArray(eventType.users) ? eventType.users : []),
    ...(Array.isArray(eventType.hosts) ? eventType.hosts : []),
  ]
    .map(toRecord)
    .filter((record): record is Record<string, unknown> => record != null)
    .map(getAvatarName)
    .filter((name) => name !== "Unknown user");

  if (options.dynamic) {
    return profileName ?? getHostIdentityLabel(userNames, host.hostName);
  }

  if (schedulingType === "ROUND_ROBIN") {
    // The design system hides the name with the avatar.
    const metadata = toRecord(eventType.metadata);
    if (
      getBooleanValue(eventType.roundRobinHideOrgAndTeam) ||
      getBooleanValue(metadata?.roundRobinHideOrgAndTeam)
    ) {
      return "";
    }
    return profileName ?? host.hostName;
  }

  if (schedulingType === "COLLECTIVE") {
    const firstName = userNames[0];
    if (profileName && firstName && profileName !== firstName) {
      return profileName;
    }

    return getHostIdentityLabel(userNames, host.hostName);
  }

  return host.hostName;
}

function parseLocationOption(value: unknown): EventTypeLocationOption | null {
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) {
      return null;
    }

    return { label: prettifyLocation(trimmed), provider: "" };
  }

  if (!value || typeof value !== "object") {
    return null;
  }

  const loc = value as Record<string, unknown>;
  const integrationProvider = getIntegrationProvider(loc);
  const provider = integrationProvider || getStringValue(loc.type) || "";
  const rawText =
    getDisplayLocationText(loc.label, integrationProvider) ??
    getDisplayLocationText(loc.name, integrationProvider) ??
    (integrationProvider || null) ??
    getStringValue(loc.address) ??
    getStringValue(loc.location) ??
    getStringValue(loc.value) ??
    getStringValue(loc.type);

  if (!rawText) {
    return null;
  }

  return {
    label: prettifyLocation(rawText),
    provider,
  };
}

function extractLocations(
  record: Record<string, unknown>,
): EventTypeLocationOption[] {
  const locationsRaw = record.locations;
  if (Array.isArray(locationsRaw) && locationsRaw.length > 0) {
    const parsed = locationsRaw
      .map(parseLocationOption)
      .filter((item): item is EventTypeLocationOption => item != null);
    if (parsed.length > 0) {
      return parsed;
    }
  }

  if (typeof record.location === "string" && record.location.trim()) {
    return [{ label: prettifyLocation(record.location), provider: "" }];
  }

  // As the design system: no locations, no location row.
  return [];
}

export function extractEventTypeInfo(payload: unknown): EventTypeInfo {
  if (!payload || typeof payload !== "object") {
    return {
      eventTypeTitle: "No event type found",
      eventTypeDescription: "",
      eventTypeDurationMinutes: null,
      eventTypeDurationOptions: null,
      eventTypeLocations: [],
      eventTypeImageUrl: "",
      disableGuests: false,
    };
  }

  const record = payload as Record<string, unknown>;
  const durationValue =
    record.lengthInMinutes ??
    record.duration ??
    record.length ??
    record.minutes;
  const duration =
    typeof durationValue === "number"
      ? durationValue
      : typeof durationValue === "string" &&
          Number.isFinite(Number(durationValue))
        ? Number(durationValue)
        : null;

  const durationOptions = extractDurationOptions(record);
  const eventTypeLocations = extractLocations(record);

  return {
    eventTypeTitle: String(
      record.title ?? record.name ?? record.slug ?? "No event type found",
    ),
    eventTypeDescription: String(record.description ?? ""),
    eventTypeDurationMinutes: duration,
    eventTypeDurationOptions:
      durationOptions.length > 1 ? durationOptions : null,
    eventTypeLocations,
    eventTypeImageUrl: normalizeAvatarUrl(
      record.imageUrl ??
        record.image_url ??
        record.image ??
        record.bannerUrl ??
        record.coverImage ??
        record.coverImageUrl,
    ),
    disableGuests: record.disableGuests === true,
    splitNameField: extractSplitNameField(record.bookingFields),
    successRedirectUrl:
      typeof record.successRedirectUrl === "string" &&
      record.successRedirectUrl.trim()
        ? record.successRedirectUrl.trim()
        : undefined,
  };
}

function extractSplitNameField(
  bookingFields: unknown,
): BookerSplitNameField | undefined {
  if (!Array.isArray(bookingFields)) {
    return undefined;
  }

  const field = bookingFields.find(
    (item): item is Record<string, unknown> =>
      !!item &&
      typeof item === "object" &&
      (item as Record<string, unknown>).type === "splitName",
  );
  if (!field) {
    return undefined;
  }

  return {
    firstNameLabel: getStringValue(field.firstNameLabel) ?? undefined,
    firstNamePlaceholder:
      getStringValue(field.firstNamePlaceholder) ?? undefined,
    lastNameLabel: getStringValue(field.lastNameLabel) ?? undefined,
    lastNamePlaceholder: getStringValue(field.lastNamePlaceholder) ?? undefined,
    lastNameRequired: field.lastNameRequired === true,
  };
}

function getStringValue(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value : null;
}

function getDisplayLocationText(
  value: unknown,
  integrationProvider: string,
): string | null {
  const text = getStringValue(value);
  if (!text) {
    return null;
  }

  const normalized = text.trim().toLowerCase();
  if (
    integrationProvider &&
    ["integration", "integrations"].includes(normalized)
  ) {
    return null;
  }

  return text;
}

function getIntegrationProvider(record: Record<string, unknown>): string {
  const rawType = getStringValue(record.type);
  const type = rawType?.trim().toLowerCase();
  const candidates = [
    record.value,
    record.integration,
    record.provider,
    record.app,
    record.appSlug,
    record.credentialType,
  ];
  for (const candidate of candidates) {
    const value = getStringValue(candidate);
    if (!value) {
      continue;
    }
    const normalized = value.trim().toLowerCase();
    if (
      ["integration", "integrations"].includes(type ?? "") &&
      !["integration", "integrations"].includes(normalized) &&
      /^[a-z0-9][a-z0-9:_-]*$/i.test(value)
    ) {
      return value;
    }
  }
  return "";
}

function toFiniteNumber(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }
  if (
    typeof value === "string" &&
    value.trim() !== "" &&
    Number.isFinite(Number(value))
  ) {
    return Number(value);
  }
  return null;
}

function normalizeDurationList(values: unknown[]): number[] {
  const minutes = values
    .map(toFiniteNumber)
    .filter((value): value is number => value != null && value > 0);

  return [...new Set(minutes)].sort((a, b) => a - b);
}

export function extractDurationOptions(payload: unknown): number[] {
  if (!payload || typeof payload !== "object") {
    return [];
  }

  const record = payload as Record<string, unknown>;
  const fromOptions = record.lengthInMinutesOptions;
  if (Array.isArray(fromOptions)) {
    const normalized = normalizeDurationList(fromOptions);
    if (normalized.length > 0) {
      return normalized;
    }
  }

  const metadata = record.metadata;
  if (metadata && typeof metadata === "object") {
    const multipleDuration = (metadata as Record<string, unknown>)
      .multipleDuration;
    if (Array.isArray(multipleDuration)) {
      return normalizeDurationList(multipleDuration);
    }
  }

  return [];
}

function addCalendarDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

function addBusinessDays(date: Date, days: number): Date {
  const result = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  let remaining = Math.max(0, days);
  while (remaining > 0) {
    result.setDate(result.getDate() + 1);
    const dayOfWeek = result.getDay();
    if (dayOfWeek !== 0 && dayOfWeek !== 6) {
      remaining -= 1;
    }
  }
  return result;
}

function parseDate(value: unknown): Date | null {
  if (typeof value !== "string" && typeof value !== "number") {
    return null;
  }
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

// Resolve the event type's booking window start date. For RANGE period types,
// this is the `periodStartDate`; otherwise bookings start from today.
export function extractBookingWindowStart(payload: unknown): Date | null {
  if (!payload || typeof payload !== "object") {
    return null;
  }

  const eventType = payload as Record<string, unknown>;
  const periodType =
    typeof eventType.periodType === "string"
      ? eventType.periodType.toUpperCase()
      : "";

  if (periodType === "RANGE") {
    const start = parseDate(eventType.periodStartDate);
    if (start) {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      // Never return a start date in the past.
      return start > today ? start : null;
    }
  }

  return null;
}

export function extractBookingWindowEnd(payload: unknown): Date | null {
  if (!payload || typeof payload !== "object") {
    return null;
  }

  const eventType = payload as Record<string, unknown>;
  const periodType =
    typeof eventType.periodType === "string"
      ? eventType.periodType.toUpperCase()
      : "";

  if (periodType === "RANGE") {
    return parseDate(eventType.periodEndDate);
  }

  if (periodType === "ROLLING" || periodType === "ROLLING_WINDOW") {
    const days = toFiniteNumber(eventType.periodDays);
    if (days != null) {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      return eventType.periodCountCalendarDays
        ? addCalendarDays(today, days)
        : addBusinessDays(today, days);
    }
  }

  return null;
}

// The calendar's first day of the week: the event type's, falling back to
// its first host's, Sunday when neither says.
export function extractWeekStart(payload: unknown): number {
  if (!payload || typeof payload !== "object") {
    return 0;
  }

  const eventType = payload as Record<string, unknown>;
  const owner = [eventType.users, eventType.hosts]
    .flatMap((list) => (Array.isArray(list) ? list.slice(0, 1) : []))
    .find((item): item is Record<string, unknown> =>
      Boolean(item && typeof item === "object"),
    );

  return toWeekStart(eventType.weekStart) ?? toWeekStart(owner?.weekStart) ?? 0;
}

export function getInitials(name: string): string {
  const parts = name
    .split(" ")
    .map((part) => part.trim())
    .filter(Boolean)
    .slice(0, 2);

  if (parts.length === 0) {
    return "NA";
  }

  return parts.map((part) => part[0]?.toUpperCase() ?? "").join("");
}

export function formatSelectedWeekday(date: Date, locale: string): string {
  return new Intl.DateTimeFormat(locale, {
    weekday: "short",
  }).format(date);
}

export function formatSelectedDay(date: Date, locale: string): string {
  return new Intl.DateTimeFormat(locale, {
    day: "2-digit",
  }).format(date);
}

export function formatSelectedMonth(date: Date, locale: string): string {
  return new Intl.DateTimeFormat(locale, {
    month: "short",
  }).format(date);
}

export function formatConfirmDateDetail(date: Date, locale: string): string {
  return new Intl.DateTimeFormat(locale, {
    day: "numeric",
    month: "long",
    year: "numeric",
  }).format(date);
}

function parseTimeLabel(
  label: string,
): { hours: number; minutes: number } | null {
  const [hoursRaw, minutesRaw] = label.split(":");
  const hours = Number(hoursRaw);
  const minutes = Number(minutesRaw);
  if (Number.isNaN(hours) || Number.isNaN(minutes)) {
    return null;
  }
  return { hours, minutes };
}

function formatConfirmTimePart(
  date: Date,
  locale: string,
  hour12: boolean,
  includePeriod: boolean,
): string {
  if (!hour12) {
    return new Intl.DateTimeFormat("en-GB", {
      hour: "2-digit",
      hour12: false,
      minute: "2-digit",
    }).format(date);
  }

  const parts = new Intl.DateTimeFormat(locale, {
    hour: "numeric",
    hour12: true,
    minute: "2-digit",
  }).formatToParts(date);

  return parts
    .filter(
      (part) =>
        part.type === "hour" ||
        part.type === "minute" ||
        (includePeriod && part.type === "dayPeriod") ||
        (part.type === "literal" && part.value.trim() !== ""),
    )
    .map((part) =>
      part.type === "dayPeriod" ? part.value.toLowerCase() : part.value,
    )
    .join("")
    .trim();
}

export function formatConfirmTimeRange(
  startTime: string,
  durationMinutes: number,
  hour12: boolean,
  locale: string,
): string {
  const parsed = parseTimeLabel(startTime);
  if (!parsed) {
    return startTime;
  }

  const startDate = new Date();
  startDate.setHours(parsed.hours, parsed.minutes, 0, 0);
  const endDate = new Date(startDate.getTime() + durationMinutes * 60_000);

  if (!hour12) {
    return `${formatConfirmTimePart(startDate, locale, false, false)} – ${formatConfirmTimePart(endDate, locale, false, false)}`;
  }

  const startParts = new Intl.DateTimeFormat(locale, {
    hour: "numeric",
    hour12: true,
    minute: "2-digit",
  }).formatToParts(startDate);
  const endParts = new Intl.DateTimeFormat(locale, {
    hour: "numeric",
    hour12: true,
    minute: "2-digit",
  }).formatToParts(endDate);
  const startPeriod = startParts
    .find((part) => part.type === "dayPeriod")
    ?.value.toLowerCase();
  const endPeriod = endParts
    .find((part) => part.type === "dayPeriod")
    ?.value.toLowerCase();
  const samePeriod = startPeriod === endPeriod;

  return `${formatConfirmTimePart(startDate, locale, true, !samePeriod)} – ${formatConfirmTimePart(endDate, locale, true, true)}`;
}

export function toDateKey(date: Date, timeZone: string): string {
  return new Intl.DateTimeFormat("en-CA", {
    day: "2-digit",
    month: "2-digit",
    timeZone,
    year: "numeric",
  }).format(date);
}

// Calendar grid dates are plain Y-M-D values (local Date components), not
// instants. Use this when looking up slots keyed by the API/booking timezone.
export function toCalendarDateKey(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export function buildBookingStartIso(
  dateKey: string,
  selectedTime: string,
  timeZone: string,
): string {
  const parsed = parseTimeLabel(selectedTime);
  if (!parsed) {
    throw new Error("Invalid time slot.");
  }

  const dateParts = dateKey.split("-");
  const year = Number(dateParts[0]);
  const month = Number(dateParts[1]);
  const day = Number(dateParts[2]);
  if (Number.isNaN(year) || Number.isNaN(month) || Number.isNaN(day)) {
    throw new Error("Invalid booking date.");
  }

  const { hours, minutes } = parsed;
  const utcGuess = Date.UTC(year, month - 1, day, hours, minutes, 0);
  const formatter = new Intl.DateTimeFormat("en-US", {
    day: "2-digit",
    hour: "2-digit",
    hour12: false,
    minute: "2-digit",
    month: "2-digit",
    second: "2-digit",
    timeZone,
    year: "numeric",
  });
  const parts = formatter.formatToParts(new Date(utcGuess));
  const get = (type: Intl.DateTimeFormatPartTypes) =>
    Number(parts.find((part) => part.type === type)?.value);
  const asUtc = Date.UTC(
    get("year"),
    get("month") - 1,
    get("day"),
    get("hour") % 24,
    get("minute"),
    get("second"),
  );
  const offset = asUtc - utcGuess;

  return new Date(utcGuess - offset).toISOString();
}

export function getTodayInTimeZone(
  timeZone: string,
  now: Date = new Date(),
): Date {
  const [yearRaw, monthRaw, dayRaw] = toDateKey(now, timeZone).split("-");
  const year = Number(yearRaw);
  const month = Number(monthRaw);
  const day = Number(dayRaw);
  if (Number.isNaN(year) || Number.isNaN(month) || Number.isNaN(day)) {
    const fallback = new Date(now);
    fallback.setHours(0, 0, 0, 0);
    return fallback;
  }
  return new Date(year, month - 1, day);
}

export function getMinimumNavigableMonth(
  timeZone: string,
  bookingWindowStart?: Date | null,
  now: Date = new Date(),
): Date {
  const todayInTz = getTodayInTimeZone(timeZone, now);
  const startBase =
    bookingWindowStart && bookingWindowStart > todayInTz
      ? bookingWindowStart
      : todayInTz;
  return new Date(startBase.getFullYear(), startBase.getMonth(), 1);
}

export function isCalendarMonthBefore(left: Date, right: Date): boolean {
  const leftMonth = new Date(left.getFullYear(), left.getMonth(), 1);
  const rightMonth = new Date(right.getFullYear(), right.getMonth(), 1);
  return leftMonth.getTime() < rightMonth.getTime();
}

export function toTimeLabel(date: Date, timeZone: string): string {
  return new Intl.DateTimeFormat("en-GB", {
    hour: "2-digit",
    hour12: false,
    minute: "2-digit",
    timeZone,
  }).format(date);
}

// Whether a locale conventionally shows time in 24-hour form, used to seed the
// 12h/24h toggle (e.g. en-US → 12h, most of Europe → 24h). Falls back to 24h.
export function prefers24Hour(locale: string): boolean {
  try {
    const resolved = new Intl.DateTimeFormat(locale, {
      hour: "numeric",
    }).resolvedOptions();
    if (typeof resolved.hour12 === "boolean") {
      return !resolved.hour12;
    }
    return resolved.hourCycle === "h23" || resolved.hourCycle === "h24";
  } catch {
    return true;
  }
}

// Slots are stored as 24h "HH:mm" strings (stable ids); reformat for display.
export function displayTimeLabel(label: string, hour12: boolean): string {
  if (!hour12) {
    return label;
  }
  const [hoursRaw, minutesRaw] = label.split(":");
  const hours = Number(hoursRaw);
  const minutes = Number(minutesRaw);
  if (Number.isNaN(hours) || Number.isNaN(minutes)) {
    return label;
  }
  const date = new Date();
  date.setHours(hours, minutes, 0, 0);
  const parts = new Intl.DateTimeFormat(undefined, {
    hour: "numeric",
    hour12: true,
    minute: "2-digit",
  }).formatToParts(date);
  return parts
    .filter((part) => part.type !== "literal" || part.value.trim() !== "")
    .map((part) =>
      part.type === "dayPeriod" ? part.value.toLowerCase() : part.value,
    )
    .join("");
}

export function isSingleDigit12HourLabel(label: string): boolean {
  const hours = Number(label.split(":")[0]);
  if (Number.isNaN(hours)) {
    return false;
  }

  const normalizedHours = hours % 12 || 12;
  return normalizedHours < 10;
}

function parseSlotDate(value: unknown): Date | null {
  if (typeof value === "string") {
    if (/^\d{2}:\d{2}$/.test(value)) {
      return null;
    }
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }

  if (!value || typeof value !== "object") {
    return null;
  }

  const record = value as Record<string, unknown>;
  const candidate =
    record.start ??
    record.startTime ??
    record.time ??
    record.dateTime ??
    record.date;

  return parseSlotDate(candidate);
}

export function extractSlotsByDate(
  payload: unknown,
  timeZone: string,
): Record<string, string[]> {
  const byDate = new Map<string, Set<string>>();
  const addSlot = (dateKey: string, time: string) => {
    if (!byDate.has(dateKey)) {
      byDate.set(dateKey, new Set<string>());
    }
    byDate.get(dateKey)?.add(time);
  };

  if (!payload || typeof payload !== "object") {
    return {};
  }

  const visitNode = (node: unknown) => {
    if (!node || typeof node !== "object") {
      return;
    }

    if (Array.isArray(node)) {
      for (const item of node) {
        visitNode(item);
      }
      return;
    }

    const record = node as Record<string, unknown>;

    for (const [key, value] of Object.entries(record)) {
      if (/^\d{4}-\d{2}-\d{2}$/.test(key) && Array.isArray(value)) {
        for (const slot of value) {
          if (typeof slot === "string" && /^\d{2}:\d{2}$/.test(slot)) {
            addSlot(key, slot);
            continue;
          }

          const parsed = parseSlotDate(slot);
          if (!parsed) {
            continue;
          }

          addSlot(toDateKey(parsed, timeZone), toTimeLabel(parsed, timeZone));
        }
      } else {
        visitNode(value);
      }
    }
  };

  visitNode(payload);

  const result: Record<string, string[]> = {};
  for (const [key, times] of byDate.entries()) {
    result[key] = Array.from(times).sort((a, b) => a.localeCompare(b));
  }

  return result;
}

// Event's minimum booking notice in minutes (cal.com `minimumBookingNotice`).
export function extractMinimumBookingNotice(payload: unknown): number {
  if (!payload || typeof payload !== "object") {
    return 0;
  }
  const minutes = toFiniteNumber(
    (payload as Record<string, unknown>).minimumBookingNotice,
  );
  return minutes != null && minutes > 0 ? minutes : 0;
}

// Drop slots that are no longer bookable: anything earlier than now plus the
// minimum booking notice, evaluated in the booking timezone. Future days are
// kept untouched; only the boundary day is partially filtered. Guards against
// showing already-passed times for today (and as the session ages).
export function filterBookableSlots(
  slotsByDate: Record<string, string[]>,
  timeZone: string,
  noticeMinutes: number,
  now: Date,
): Record<string, string[]> {
  const cutoff = new Date(now.getTime() + noticeMinutes * 60_000);
  const cutoffDateKey = toDateKey(cutoff, timeZone);
  const [cutoffHoursRaw, cutoffMinutesRaw] = toTimeLabel(
    cutoff,
    timeZone,
  ).split(":");
  const cutoffHours = Number(cutoffHoursRaw);
  const cutoffMinutes = Number(cutoffMinutesRaw);
  if (Number.isNaN(cutoffHours) || Number.isNaN(cutoffMinutes)) {
    return slotsByDate;
  }
  const cutoffOfDay = cutoffHours * 60 + cutoffMinutes;

  const result: Record<string, string[]> = {};
  for (const [dateKey, times] of Object.entries(slotsByDate)) {
    if (dateKey < cutoffDateKey) {
      continue;
    }
    if (dateKey > cutoffDateKey) {
      result[dateKey] = times;
      continue;
    }
    const kept = times.filter((time) => {
      const [hoursRaw, minutesRaw] = time.split(":");
      const hours = Number(hoursRaw);
      const minutes = Number(minutesRaw);
      if (Number.isNaN(hours) || Number.isNaN(minutes)) {
        return false;
      }
      return hours * 60 + minutes >= cutoffOfDay;
    });
    if (kept.length > 0) {
      result[dateKey] = kept;
    }
  }
  return result;
}

export function findFirstAvailableDate(
  month: Date,
  slotsByDate: Record<string, string[]>,
  _timeZone: string,
  todayStart: Date,
): Date | null {
  const year = month.getFullYear();
  const monthIndex = month.getMonth();
  const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
  const todayKey = toCalendarDateKey(todayStart);

  for (let day = 1; day <= daysInMonth; day += 1) {
    const date = new Date(year, monthIndex, day);
    const key = toCalendarDateKey(date);
    if (key < todayKey) {
      continue;
    }

    if ((slotsByDate[key] ?? []).length > 0) {
      return date;
    }
  }

  return null;
}

// --- Calendar grid (mirrors booker-calendar.tsx) ---

function calendarStartOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), 1);
}

function calendarEndOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0);
}

function calendarAddDays(date: Date, amount: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + amount);
}

function calendarStartOfWeek(date: Date, weekStartsOn = 0): Date {
  const day = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const diff = (day.getDay() - weekStartsOn + 7) % 7;
  return calendarAddDays(day, -diff);
}

function calendarEndOfWeek(date: Date, weekStartsOn = 0): Date {
  return calendarAddDays(calendarStartOfWeek(date, weekStartsOn), 6);
}

function isSameCalendarMonth(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
}

export type CalendarViewOptions = {
  weekStartsOn?: number;
  shiftWeeks?: boolean;
  startMonth?: Date;
  endMonth?: Date;
};

export function getVisibleCalendarDates(
  month: Date,
  today: Date,
  options: CalendarViewOptions = {},
): Date[] {
  const weekStartsOn = options.weekStartsOn ?? 0;
  const shiftWeeks = options.shiftWeeks ?? true;
  const firstMonth = calendarStartOfMonth(month);

  const naturalGridStart = calendarStartOfWeek(firstMonth, weekStartsOn);
  const todayStart = new Date(
    today.getFullYear(),
    today.getMonth(),
    today.getDate(),
  );
  const todayRow = Math.floor(
    Math.round(
      (todayStart.getTime() - naturalGridStart.getTime()) / 86_400_000,
    ) / 7,
  );
  const expand =
    shiftWeeks && isSameCalendarMonth(firstMonth, today) && todayRow >= 3;
  const shiftRows = expand ? Math.max(0, todayRow - 3) : 0;

  const monthStart = calendarStartOfMonth(firstMonth);
  const offset = shiftRows * 7;
  const gridStart = calendarAddDays(
    calendarStartOfWeek(monthStart, weekStartsOn),
    offset,
  );
  const gridEnd = calendarAddDays(
    calendarEndOfWeek(calendarEndOfMonth(firstMonth), weekStartsOn),
    offset,
  );

  const dates: Date[] = [];
  for (
    let cursor = gridStart;
    cursor.getTime() <= gridEnd.getTime();
    cursor = calendarAddDays(cursor, 1)
  ) {
    dates.push(cursor);
  }

  if (expand) {
    while (dates.length < 42) {
      const lastDate = dates.at(-1);
      if (!lastDate) {
        break;
      }
      dates.push(calendarAddDays(lastDate, 1));
    }
  }

  const navStart = options.startMonth
    ? calendarStartOfMonth(options.startMonth)
    : undefined;
  const navEnd = options.endMonth
    ? calendarStartOfMonth(options.endMonth)
    : undefined;
  const monthEnd = calendarEndOfMonth(firstMonth);

  return dates.filter((date) => {
    if (navStart && date < navStart) {
      return false;
    }
    if (navEnd && date > calendarEndOfMonth(navEnd)) {
      return false;
    }
    if (date < monthStart) {
      return false;
    }
    if (!expand && date > monthEnd) {
      return false;
    }
    return true;
  });
}

export function findFirstAvailableInVisibleGrid(
  month: Date,
  slotsByDate: Record<string, string[]>,
  todayStart: Date,
  options: CalendarViewOptions = {},
): Date | null {
  const todayKey = toCalendarDateKey(todayStart);
  for (const date of getVisibleCalendarDates(month, todayStart, options)) {
    const key = toCalendarDateKey(date);
    if (key < todayKey) {
      continue;
    }
    if ((slotsByDate[key] ?? []).length > 0) {
      return date;
    }
  }
  return null;
}

export function hasAvailabilityInVisibleGrid(
  month: Date,
  slotsByDate: Record<string, string[]>,
  todayStart: Date,
  options: CalendarViewOptions = {},
): boolean {
  return (
    findFirstAvailableInVisibleGrid(month, slotsByDate, todayStart, options) !=
    null
  );
}

export function pickDefaultSelectedDate(
  currentMonth: Date,
  slotsByDate: Record<string, string[]>,
  _timeZone: string,
  todayStart: Date,
  viewOptions?: CalendarViewOptions,
): Date | null {
  if (viewOptions) {
    return findFirstAvailableInVisibleGrid(
      currentMonth,
      slotsByDate,
      todayStart,
      viewOptions,
    );
  }

  return findFirstAvailableDate(
    currentMonth,
    slotsByDate,
    _timeZone,
    todayStart,
  );
}

// Earliest loaded date (today or later) that still has open slots, used to
// offer a "jump to next availability" affordance from an empty month/day.
export function findNextAvailableDate(
  slotsByDate: Record<string, string[]>,
  _timeZone: string,
  todayStart: Date,
): Date | null {
  const todayKey = toCalendarDateKey(todayStart);
  let bestKey: string | null = null;
  for (const [key, times] of Object.entries(slotsByDate)) {
    if (times.length === 0 || key < todayKey) {
      continue;
    }
    if (bestKey === null || key < bestKey) {
      bestKey = key;
    }
  }

  if (!bestKey) {
    return null;
  }

  const [yearRaw, monthRaw, dayRaw] = bestKey.split("-");
  const year = Number(yearRaw);
  const month = Number(monthRaw);
  const day = Number(dayRaw);
  if (Number.isNaN(year) || Number.isNaN(month) || Number.isNaN(day)) {
    return null;
  }
  return new Date(year, month - 1, day);
}

import type { BookingLocationInput } from "./cal-api/types";

const BOOKING_INTEGRATION_MAP: Record<string, string> = {
  "daily-video": "daily-video",
  "google-meet": "google-meet",
  "huddle01-video": "huddle",
  "microsoft-teams": "office365-video",
  whereby: "whereby-video",
};

export function toBookingLocation(provider: string): BookingLocationInput {
  const normalized = provider.trim().toLowerCase();

  if (normalized === "inperson" || normalized === "in_person") {
    return { type: "address" };
  }

  if (normalized === "phone") {
    return { type: "phone" };
  }

  if (normalized === "conferencing" || normalized === "organizersdefaultapp") {
    return { type: "organizersDefaultApp" };
  }

  if (normalized === "link") {
    return { type: "link" };
  }

  const integration = BOOKING_INTEGRATION_MAP[normalized] ?? normalized;
  return { type: "integration", integration };
}

// Event descriptions as Cal's own Booker renders them: a copy of the browser
// path of Cal's markdown adapter (calcom/cal `packages/infra/adapters/markdown`:
// `markdown-it.ts`, `merge-split-nested-lists.ts`, and `toProseHtml` in
// `dompurify-markdown-adapter.ts`). API v2 returns the description as raw
// markdown, which may contain raw HTML, so it is sanitized here.

import DOMPurify from "dompurify";
import MarkdownIt from "markdown-it";

const md = new MarkdownIt("default", {
  breaks: true,
  html: true,
  linkify: true,
});

// The description editor serializes a nested list as a sibling `<li><ul>…</ul></li>`.
// Match: <li>Some text </li><li><ul>...</ul></li>
// Convert to: <li>Some text <ul>...</ul></li>
function mergeSplitNestedLists(html: string): string {
  return html.replace(
    /<li>([^<]+|<strong>.*?<\/strong>)<\/li>\s*<li>\s*<ul([^>]*)>([\s\S]*?)<\/ul>\s*<\/li>/g,
    "<li>$1<ul$2>$3</ul></li>",
  );
}

/**
 * Sanitized HTML for a styled container: no inline styles or link classes.
 * Without a DOM (a server render) DOMPurify cannot sanitize, so this returns
 * an empty string; call it in the browser.
 */
export function markdownToSafeHtml(markdown: string | null): string {
  if (!markdown || !DOMPurify.isSupported) return "";

  const fragment = DOMPurify.sanitize(md.render(markdown), {
    RETURN_DOM_FRAGMENT: true,
  });
  for (const anchor of fragment.querySelectorAll("a")) {
    anchor.setAttribute("target", "_blank");
    anchor.setAttribute("rel", "noopener noreferrer nofollow ugc");
  }
  const container = document.createElement("div");
  container.appendChild(fragment);

  return mergeSplitNestedLists(container.innerHTML);
}

