};

export type ParsedLinkTarget =
  | {
      type: "user";
      username: string;
      eventSlug: string;
      orgId?: number;
      orgSlug?: string;
    }
  | {
      type: "dynamic";
      usernames: string[];
      orgId?: number;
      orgSlug?: string;
    }
  | {
      type: "teamSlug";
      teamSlug: string;
      eventSlug: string;
      orgId?: number;
      orgSlug?: string;
    };

const DYNAMIC_EVENT_SLUG = "dynamic";

function parsePositiveInt(value: string | null): number | undefined {
  if (!value) {
    return undefined;
  }

  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed > 0 ? parsed : undefined;
}

function toUrl(value: string): URL {
  const trimmed = value.trim();
  if (!trimmed) {
    throw new Error("Pass a non-empty bookingUrl.");
  }

  if (/^https?:\/\//i.test(trimmed)) {
    return new URL(trimmed);
  }

  return new URL(`https://${trimmed}`);
}

function parseOrgSlugFromHostname(hostname: string): string | undefined {
  const match = hostname.match(/^([a-z0-9-]+)\.cal\.com$/i);
  const subdomain = match?.[1]?.toLowerCase();

  if (!subdomain) {
    return undefined;
  }

  if (["api", "app", "cal", "www"].includes(subdomain)) {
    return undefined;
  }

  return subdomain;
}

function parseDynamicUsernames(
  pathUsername: string,
  userParam: string | null,
): string[] {
  const source = userParam ?? decodeURIComponent(pathUsername);
  return source
    .split(/[+,\s]+/)
    .map((part) => part.trim())
    .filter(Boolean);
}

export function getOrgSlugFromTarget(target: BookerTarget): string | undefined {
  if (target.type === "dynamic") {
    return target.orgSlug;
  }

  if (target.type === "link") {
    return parseBookingUrlTarget(target.bookingUrl, target.orgId).orgSlug;
  }

  return undefined;
}

export function getUserSlotParamsFromTarget(
  target: BookerTarget,
): { username: string; eventTypeSlug: string } | null {
  const params = getCreateBookingParamsFromTarget(target);
  if (!params.username || !params.eventTypeSlug) {
    return null;
  }

  return { eventTypeSlug: params.eventTypeSlug, username: params.username };
}

export type CreateBookingTargetParams = {
  eventTypeSlug?: string;
  organizationSlug?: string;
  teamSlug?: string;
  username?: string;
};

export function getCreateBookingParamsFromTarget(
  target: BookerTarget,
  resolved?: { eventTypeSlug?: string | null },
): CreateBookingTargetParams {
  if (target.type === "user") {
    return {
      eventTypeSlug: target.eventSlug,
      organizationSlug: getOrgSlugFromTarget(target),
      username: target.username,
    };
  }

  if (target.type === "team") {
    return {
      eventTypeSlug: target.eventSlug,
      organizationSlug: getOrgSlugFromTarget(target),
    };
  }

  if (target.type === "link") {
    const parsed = parseBookingUrlTarget(target.bookingUrl, target.orgId);
    if (parsed.type === "user") {
      return {
        eventTypeSlug: parsed.eventSlug,
        organizationSlug: parsed.orgSlug,
        username: parsed.username,
      };
    }

    if (parsed.type === "teamSlug") {
      return {
        eventTypeSlug: parsed.eventSlug,
        organizationSlug: parsed.orgSlug,
        teamSlug: parsed.teamSlug,
      };
    }
  }

  return {
    eventTypeSlug: resolved?.eventTypeSlug ?? undefined,
    organizationSlug: getOrgSlugFromTarget(target),
  };
}

export function getPublicEventBannerParamsFromTarget(target: BookerTarget): {
  username: string;
  eventSlug: string;
  orgSlug: string;
  isTeamEvent?: boolean;
} | null {
  if (target.type !== "link") {
    return null;
  }

  const parsed = parseBookingUrlTarget(target.bookingUrl, target.orgId);
  if (!parsed.orgSlug) {
    return null;
  }

  if (parsed.type === "user") {
    return {
      eventSlug: parsed.eventSlug,
      orgSlug: parsed.orgSlug,
      username: parsed.username,
    };
  }

  if (parsed.type === "teamSlug") {
    return {
      eventSlug: parsed.eventSlug,
      isTeamEvent: true,
      orgSlug: parsed.orgSlug,
      username: parsed.teamSlug,
    };
  }

  if (parsed.type === "dynamic") {
    return {
      eventSlug: "dynamic",
      orgSlug: parsed.orgSlug,
      username: parsed.usernames.join("+"),
    };
  }

  return null;
}

export function getDynamicContext(
  target: BookerTarget,
): DynamicTargetContext | null {
  if (target.type === "dynamic") {
    return {
      orgId: target.orgId,
      orgSlug: target.orgSlug,
      usernames: target.usernames,
    };
  }

  if (target.type === "link") {
    const parsed = parseBookingUrlTarget(target.bookingUrl, target.orgId);
    if (parsed.type === "dynamic") {
      return {
        orgId: parsed.orgId,
        orgSlug: parsed.orgSlug,
        usernames: parsed.usernames,
      };
    }
  }

  return null;
}

export function parseBookingUrlTarget(
  bookingUrl: string,
  fallbackOrgId?: number,
): ParsedLinkTarget {
  const url = toUrl(bookingUrl);
  const parts = url.pathname.split("/").filter(Boolean);
  const orgId =
    parsePositiveInt(url.searchParams.get("orgId")) ?? fallbackOrgId;
  const orgSlug = parseOrgSlugFromHostname(url.hostname);

  if (parts.length < 2) {
    throw new Error(
      "bookingUrl must include at least username/team and eventSlug.",
    );
  }

  if (parts[0] === "team" && parts.length >= 3) {
    return {
      eventSlug: decodeURIComponent(parts[2] ?? ""),
      orgId,
      orgSlug,
      teamSlug: decodeURIComponent(parts[1] ?? ""),
      type: "teamSlug",
    };
  }

  const eventSlug = decodeURIComponent(parts[1] ?? "");
  const pathUsername = decodeURIComponent(parts[0] ?? "");

  if (eventSlug === DYNAMIC_EVENT_SLUG) {
    const usernames = parseDynamicUsernames(
      pathUsername,
      url.searchParams.get("user"),
    );
    if (usernames.length >= 2) {
      return { orgId, orgSlug, type: "dynamic", usernames };
    }
  }

  return {
    eventSlug,
    orgId,
    orgSlug,
    type: "user",
    username: pathUsername,
  };
}

export function normalizeLegacyTarget(
  props: LegacyBookerTargetInput,
): BookerTarget {
  if (props.bookingUrl) {
    return { bookingUrl: props.bookingUrl, orgId: props.orgId, type: "link" };
  }

  if (props.isTeamEvent) {
    if (!props.teamId || !props.eventSlug) {
      throw new Error(
        "For team events, pass teamId and eventSlug in target or legacy props.",
      );
    }

    return {
      eventSlug: props.eventSlug,
      orgId: props.orgId,
      teamId: props.teamId,
      type: "team",
    };
  }

  const username = Array.isArray(props.username)
    ? props.username.join("+")
    : props.username;
  if (!username || !props.eventSlug) {
    throw new Error("Pass target or username + eventSlug.");
  }

  return {
    eventSlug: props.eventSlug,
    orgId: props.orgId,
    type: "user",
    username,
  };
}

"use client";

import { ExternalLinkIcon, MapPinIcon } from "lucide-react";
import { useMemo, useState } from "react";
import { Field, FieldLabel } from "@/registry/default/ui/field";
import {
  Popover,
  PopoverDescription,
  PopoverPopup,
  PopoverTrigger,
} from "@/registry/default/ui/popover";
import {
  Select,
  SelectItem,
  SelectPopup,
  SelectTrigger,
  SelectValue,
} from "@/registry/default/ui/select";
import type { EventTypeLocationOption } from "./lib/booker-utils";

type LocationLabels = {
  locationOptions: (count: number) => string;
  selectOnNextStep: string;
};

type LocationProps = {
  locations: EventTypeLocationOption[];
  labels: LocationLabels;
};

const PROVIDER_ICON_MAP: Record<string, string> = {
  "cal-video": "https://app.cal.com/app-store/dailyvideo/icon.svg",
  "daily-video": "https://app.cal.com/app-store/dailyvideo/icon.svg",
  "google-meet": "https://i.cal.com/app-store/googlevideo/logo.webp",
  "huddle01-video": "/app-store/huddle01video/icon.svg",
  "microsoft-teams": "/app-store/office365video/icon.svg",
  conferencing: "external-link",
  jitsi: "/app-store/jitsivideo/icon.svg",
  organizersdefaultapp: "external-link",
  whereby: "/app-store/whereby/icon-dark.svg",
  zoom: "/app-store/zoomvideo/icon.svg",
};

function normalizeIconUrl(value: string): string {
  if (value.startsWith("http://") || value.startsWith("https://")) {
    return value;
  }

  if (value.startsWith("/")) {
    return `https://app.cal.com${value}`;
  }

  return value;
}

function resolveProviderIcons(provider?: string): string[] {
  if (!provider) {
    return [];
  }

  const normalized = provider.trim().toLowerCase();
  if (!normalized) {
    return [];
  }

  const appStoreSlugs = new Set<string>([
    normalized,
    normalized.replaceAll("-", ""),
  ]);
  if (normalized.endsWith("-video")) {
    appStoreSlugs.add(normalized.replace(/-video$/, "video"));
  }

  return Array.from(
    new Set([
      PROVIDER_ICON_MAP[normalized],
      ...Array.from(
        appStoreSlugs,
        (slug) => `https://app.cal.com/app-store/${slug}/icon.svg`,
      ),
    ]),
  )
    .filter((url): url is string => Boolean(url))
    .map(normalizeIconUrl);
}

const failedIconUrls = new Set<string>();

export function LocationIcon({
  provider,
  small = false,
}: {
  provider?: string;
  /** The design system's popover list uses 14px icons. */
  small?: boolean;
}) {
  const symbolClassName = small
    ? "size-3.5 shrink-0 opacity-80"
    : "size-4.5 shrink-0 opacity-80 sm:size-4";
  const iconUrls = useMemo(() => resolveProviderIcons(provider), [provider]);
  // Failed addresses are remembered across mounts, so reopening the location
  // popover goes straight to the address that works instead of retrying from
  // the first one (which made the icons flash).
  const [, setFailureCount] = useState(0);
  const iconUrl =
    iconUrls.find((candidate) => !failedIconUrls.has(candidate)) ?? "";

  if (iconUrl) {
    if (iconUrl === "external-link") {
      return (
        <ExternalLinkIcon aria-hidden="true" className={symbolClassName} />
      );
    }

    return (
      <img
        alt=""
        aria-hidden="true"
        className={small ? "size-3.5 shrink-0" : "size-4.5 shrink-0 sm:size-4"}
        onError={() => {
          failedIconUrls.add(iconUrl);
          setFailureCount((count) => count + 1);
        }}
        src={iconUrl}
      />
    );
  }

  return <MapPinIcon aria-hidden="true" className={symbolClassName} />;
}

export function LocationRow({ label, provider }: EventTypeLocationOption) {
  return (
    <div className="flex items-center gap-2">
      <LocationIcon provider={provider} />
      <span>{label}</span>
    </div>
  );
}

export function getLocationOptionValue(
  location: EventTypeLocationOption,
  index: number,
): string {
  return location.provider || `${location.label}-${index}`;
}

type LocationSelectItem = EventTypeLocationOption & {
  value: string;
};

type LocationPickerProps = {
  locations: EventTypeLocationOption[];
  label: string;
  onValueChange?: (provider: string) => void;
};

function LocationSelectOption({ label, provider }: LocationSelectItem) {
  return (
    <span className="flex items-center gap-2">
      <LocationIcon provider={provider} />
      <span className="truncate">{label}</span>
    </span>
  );
}

export function LocationPicker({
  locations,
  label,
  onValueChange,
}: LocationPickerProps) {
  const items = useMemo(
    (): LocationSelectItem[] =>
      locations.map((location, index) => ({
        ...location,
        value: getLocationOptionValue(location, index),
      })),
    [locations],
  );

  if (items.length <= 1) {
    return null;
  }

  return (
    <Field name="location">
      <FieldLabel>{label}</FieldLabel>
      <Select
        aria-label={label}
        defaultValue={items[0]}
        itemToStringValue={(item) => item.value}
        onValueChange={(item) => {
          if (item) {
            onValueChange?.(item.provider || item.value);
          }
        }}
      >
        <SelectTrigger>
          <SelectValue>
            {(item) => <LocationSelectOption {...item} />}
          </SelectValue>
        </SelectTrigger>
        <SelectPopup>
          {items.map((item) => (
            <SelectItem key={item.value} value={item}>
              <LocationSelectOption {...item} />
            </SelectItem>
          ))}
        </SelectPopup>
      </Select>
    </Field>
  );
}

export function Location({ locations, labels }: LocationProps) {
  if (locations.length <= 1) {
    const location = locations[0];
    return location ? <LocationRow {...location} /> : null;
  }

  return (
    <Popover>
      <PopoverTrigger
        aria-label={labels.locationOptions(locations.length)}
        className="flex w-fit items-center gap-2 decoration-current/32 decoration-dotted underline-offset-2 hover:text-foreground hover:underline"
        openOnHover
        delay={0}
      >
        <MapPinIcon
          aria-hidden="true"
          className="h-lh w-4.5 shrink-0 opacity-80 sm:w-4"
        />
        <span>{labels.locationOptions(locations.length)}</span>
      </PopoverTrigger>
      <PopoverPopup align="start" side="top" className="*:p-3">
        <PopoverDescription className="mb-2 font-medium text-muted-foreground text-xs">
          {labels.selectOnNextStep}
        </PopoverDescription>
        <ul className="flex flex-col gap-2">
          {locations.map((location, index) => (
            <li
              className="flex items-center gap-2 font-medium text-xs"
              key={`${location.label}-${location.provider}-${index}`}
            >
              <LocationIcon provider={location.provider} small />
              <span>{location.label}</span>
            </li>
          ))}
        </ul>
      </PopoverPopup>
    </Popover>
  );
}

// A copy of Cal's shared ResponseCard
// (calcom/cal `packages/coss-ui/src/shared/response-card.tsx`), the card Cal
// Video shows for its errors. Only the import paths differ.

import type React from "react";
import { cn } from "@/registry/default/lib/utils";
import {
  Card,
  CardDescription,
  CardFrame,
  CardFrameFooter,
  CardPanel,
  CardTitle,
} from "@/registry/default/ui/card";
import { StatusMark, type StatusMarkStatus } from "./status-mark";

export type ResponseCardProps = {
  title: React.ReactNode;
  description?: React.ReactNode;
  status?: StatusMarkStatus;
  icon?: React.ReactNode;
  children?: React.ReactNode;
  action?: React.ReactNode;
  footer?: React.ReactNode;
  className?: string;
  titleProps?: {
    id?: string;
    "data-testid"?: string;
  };
  "data-testid"?: string;
};

export function ResponseCard({
  title,
  description,
  status,
  icon,
  children,
  action,
  footer,
  className,
  titleProps,
  "data-testid": dataTestId,
}: ResponseCardProps): React.ReactElement {
  const hasFooter = footer !== undefined && footer !== null && footer !== false;
  const card = (
    <Card
      className={cn(!hasFooter && "w-full max-w-md", !hasFooter && className)}
      data-testid={hasFooter ? undefined : dataTestId}
    >
      <CardPanel className="py-10">
        <div className="flex flex-col items-center gap-6 text-center">
          <div className="flex flex-col items-center gap-4">
            <StatusMark status={status} icon={icon} />
            <div className="flex flex-col items-center gap-2">
              <CardTitle
                className="font-bold font-heading text-xl leading-none"
                // biome-ignore lint/a11y/useHeadingContent: CardTitle renders the title into it
                render={<h1 />}
                {...titleProps}
              >
                {title}
              </CardTitle>
              {description ? (
                <CardDescription>{description}</CardDescription>
              ) : null}
            </div>
          </div>
          {children !== undefined && children !== null ? (
            <div className="flex w-full flex-col items-center gap-3">
              {children}
            </div>
          ) : null}
          {action}
        </div>
      </CardPanel>
    </Card>
  );

  if (!hasFooter) {
    return card;
  }

  return (
    <CardFrame
      className={cn("w-full max-w-md", className)}
      data-testid={dataTestId}
    >
      {card}
      <CardFrameFooter>{footer}</CardFrameFooter>
    </CardFrame>
  );
}

